screenPanels.initJs:
function(container, apiUrl, tables) {
  let studentsData = [];
  let schoolsData = [];
  let mockExamsData = [];
  let selectedMockExams = [];

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      // 受験生データ読み込み（志望校登録データから取得）
      const aspirationData = await window.aivicApi.list(15); // 志望校登録データ
      if (aspirationData) {
        const uniqueStudents = [...new Set(aspirationData.map(item => item.受験生ID))];
        studentsData = uniqueStudents.map(id => ({ id, name: `受験生${id.slice(-4)}` }));
      }

      // 志望校データ読み込み
      if (aspirationData) {
        schoolsData = aspirationData.map(item => ({
          id: item.志望校登録ID,
          name: item.学校名,
          department: item.学部名 || '',
          major: item.学科名 || '',
          requiredDeviation: item.必要偏差値 || 50
        }));
      }

      // 模試データ読み込み
      const mockData = await window.aivicApi.list(5); // 模試日程データ
      if (mockData) {
        mockExamsData = mockData.map(item => ({
          id: item.模試日程ID,
          name: item.模試名,
          date: item.実施日
        }));
      }

      renderSelectors();
    } catch (error) {
      showError('データの読み込みに失敗しました');
    }
  }

  // セレクタ描画
  function renderSelectors() {
    const studentSelect = container.querySelector('#select-student');
    const schoolSelect = container.querySelector('#select-school');
    const mockExamList = container.querySelector('#mock-exam-list');

    // 受験生選択肢
    studentSelect.innerHTML = '<option value="">受験生を選択してください</option>';
    studentsData.forEach(student => {
      studentSelect.innerHTML += `<option value="${student.id}">${student.name}</option>`;
    });

    // 志望校選択肢
    schoolSelect.innerHTML = '<option value="">志望校を選択してください</option>';
    schoolsData.forEach(school => {
      const displayName = school.department ? 
        `${school.name} ${school.department}${school.major ? ' ' + school.major : ''}` : 
        school.name;
      schoolSelect.innerHTML += `<option value="${school.id}">${displayName}</option>`;
    });

    // 模試チェックボックス
    mockExamList.innerHTML = '';
    mockExamsData.forEach(mock => {
      const mockDate = new Date(mock.date).toLocaleDateString();
      mockExamList.innerHTML += `
        <label style="display: flex; align-items: center; gap: 0.5rem;">
          <input type="checkbox" value="${mock.id}" class="mock-checkbox">
          <span>${mock.name} (${mockDate})</span>
        </label>
      `;
    });
  }

  // エラー表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    const errorText = container.querySelector('#error-text');
    errorText.textContent = message;
    errorDiv.classList.remove('hidden');

    // 診断結果を非表示
    container.querySelector('#diagnosis-results').classList.add('hidden');
  }

  // エラー非表示
  function hideError() {
    container.querySelector('#error-message').classList.add('hidden');
  }

  // 診断実行
  async function executeDiagnosis() {
    hideError();

    const studentId = container.querySelector('#select-student').value;
    const schoolId = container.querySelector('#select-school').value;
    const mockCheckboxes = container.querySelectorAll('.mock-checkbox:checked');

    // バリデーション
    if (!studentId) {
      showError('受験生を選択してください');
      return;
    }
    if (!schoolId) {
      showError('志望校を選択してください');
      return;
    }
    if (mockCheckboxes.length === 0) {
      showError('模試を選択してください');
      return;
    }

    selectedMockExams = Array.from(mockCheckboxes).map(cb => cb.value);

    try {
      // 成績データ取得
      const gradeData = await window.aivicApi.list(3); // 科目別成績データ
      const mockResults = await window.aivicApi.list(2); // 模試結果データ

      if (!gradeData || gradeData.length === 0) {
        showError('成績データが不足しているため、合格可能性診断を実行できません。先に成績データを登録してください。');
        return;
      }

      // 選択された受験生の成績データをフィルタ
      const studentGrades = gradeData.filter(grade => grade.受験生ID === studentId);
      const studentMockResults = mockResults ? mockResults.filter(result => result.受験生ID === studentId) : [];

      if (studentGrades.length === 0) {
        showError('選択された受験生の成績データが見つかりません');
        return;
      }

      // 志望校情報取得
      const selectedSchool = schoolsData.find(school => school.id === schoolId);
      if (!selectedSchool) {
        showError('指定された志望校が見つかりません');
        return;
      }

      // 診断結果計算
      const diagnosisResult = calculateDiagnosis(studentGrades, studentMockResults, selectedSchool);

      // 結果表示
      displayResults(diagnosisResult, selectedSchool);

    } catch (error) {
      showError('システムエラーが発生しました。しばらく時間をおいてから再度お試しください。');
    }
  }

  // 診断計算
  function calculateDiagnosis(grades, mockResults, school) {
    // 最新の総合偏差値を計算
    const latestGrades = grades.sort((a, b) => new Date(b.実施日) - new Date(a.実施日));
    const avgDeviation = latestGrades.length > 0 ? 
      Math.round(latestGrades.slice(0, 5).reduce((sum, grade) => sum + (grade.偏差値 || 50), 0) / Math.min(5, latestGrades.length)) : 50;

    const targetDeviation = school.requiredDeviation || 50;
    const deviationDiff = avgDeviation - targetDeviation;

    // 合格可能性計算（簡易版）
    let passProbability;
    if (deviationDiff >= 10) passProbability = 100;
    else if (deviationDiff >= 5) passProbability = 85;
    else if (deviationDiff >= 0) passProbability = 65;
    else if (deviationDiff >= -5) passProbability = 40;
    else if (deviationDiff >= -10) passProbability = 20;
    else passProbability = 5;

    // 判定レベル
    let judgment;
    if (passProbability >= 80) judgment = 'A判定';
    else if (passProbability >= 60) judgment = 'B判定';
    else if (passProbability >= 40) judgment = 'C判定';
    else if (passProbability >= 20) judgment = 'D判定';
    else judgment = 'E判定';

    // 科目別データ
    const subjectData = {};
    const subjects = ['国語', '数学', '英語', '理科', '社会'];
    subjects.forEach(subject => {
      const subjectGrades = grades.filter(g => g.科目名 === subject);
      if (subjectGrades.length > 0) {
        const latestGrade = subjectGrades.sort((a, b) => new Date(b.実施日) - new Date(a.実施日))[0];
        const subjectDeviation = latestGrade.偏差値 || 50;
        const subjectTarget = targetDeviation; // 簡略化
        const subjectDiff = subjectDeviation - subjectTarget;

        let subjectProb;
        if (subjectDiff >= 5) subjectProb = 85;
        else if (subjectDiff >= 0) subjectProb = 65;
        else if (subjectDiff >= -5) subjectProb = 40;
        else subjectProb = 20;

        subjectData[subject] = {
          currentDeviation: subjectDeviation,
          targetDeviation: subjectTarget,
          probability: subjectProb,
          judgment: subjectProb >= 60 ? 'A' : subjectProb >= 40 ? 'B' : subjectProb >= 20 ? 'C' : 'D',
          improvement: Math.max(0, subjectTarget - subjectDeviation)
        };
      }
    });

    return {
      passProbability,
      judgment,
      currentDeviation: avgDeviation,
      targetDeviation,
      improvement: Math.max(0, targetDeviation - avgDeviation),
      achievementRate: Math.min(100, Math.max(0, (avgDeviation / targetDeviation) * 100)),
      subjectData,
      progressData: grades.map(g => ({
        date: g.実施日,
        deviation: g.偏差値 || 50,
        subject: g.科目名
      }))
    };
  }

  // 結果表示
  function displayResults(result, school) {
    container.querySelector('#diagnosis-results').classList.remove('hidden');

    // 基本情報表示
    container.querySelector('#judgment-result').textContent = result.judgment;
    container.querySelector('#pass-probability').textContent = `${result.passProbability}%`;
    container.querySelector('#current-deviation').textContent = result.currentDeviation;
    container.querySelector('#target-deviation').textContent = result.targetDeviation;
    container.querySelector('#required-improvement').textContent = result.improvement > 0 ? `+${result.improvement}` : '達成済み';

    // 到達度プログレスバー
    container.querySelector('#achievement-rate').textContent = `${Math.round(result.achievementRate)}%`;
    container.querySelector('#progress-fill').style.width = `${result.achievementRate}%`;

    // 科目別テーブル
    const subjectTbody = container.querySelector('#subject-tbody');
    subjectTbody.innerHTML = '';
    Object.entries(result.subjectData).forEach(([subject, data]) => {
      subjectTbody.innerHTML += `
        <tr>
          <td>${subject}</td>
          <td>${data.currentDeviation}</td>
          <td>${data.targetDeviation}</td>
          <td>${data.probability}%</td>
          <td>${data.judgment}判定</td>
          <td>${data.improvement > 0 ? `+${data.improvement}` : '達成済み'}</td>
        </tr>
      `;
    });

    // 同偏差値帯実績データ（模擬データ）
    const similarExaminees = Math.floor(Math.random() * 500) + 100;
    const similarPassRate = Math.max(10, Math.min(90, result.passProbability + (Math.random() - 0.5) * 20));
    const similarPassers = Math.round(similarExaminees * similarPassRate / 100);

    container.querySelector('#similar-examinees').textContent = `${similarExaminees}人`;
    container.querySelector('#similar-passers').textContent = `${similarPassers}人`;
    container.querySelector('#similar-pass-rate').textContent = `${Math.round(similarPassRate)}%`;

    // 改善提案アドバイス
    let advice = '';
    if (result.passProbability >= 80) {
      advice = '現在の成績は志望校の合格ラインを上回っています。この調子で学習を継続し、本番でのケアレスミスに注意しましょう。';
    } else if (result.passProbability >= 60) {
      advice = '合格圏内にいますが、より確実にするため弱点科目の強化をお勧めします。';
    } else if (result.passProbability >= 40) {
      advice = `合格可能性を高めるため、偏差値を${result.improvement}ポイント向上させる必要があります。特に苦手科目の集中的な学習をお勧めします。`;
    } else {
      advice = `現在の成績では合格が困難です。基礎から見直し、計画的な学習が必要です。志望校の見直しも検討してください。`;
    }
    container.querySelector('#improvement-advice').innerHTML = `<p style="color: var(--text); margin: 0;">${advice}</p>`;

    // グラフ描画
    drawDeviationChart(result);
    drawProgressChart(result);
  }

  // 偏差値比較グラフ描画
  function drawDeviationChart(result) {
    const canvas = container.querySelector('#deviation-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const subjects = Object.keys(result.subjectData);
    const barWidth = canvas.width / (subjects.length + 1);
    const maxDeviation = 80;

    subjects.forEach((subject, index) => {
      const data = result.subjectData[subject];
      const x = (index + 1) * barWidth - barWidth/2;

      // 現在偏差値バー
      const currentHeight = (data.currentDeviation / maxDeviation) * (canvas.height - 60);
      ctx.fillStyle = '#3498db';
      ctx.fillRect(x - 15, canvas.height - currentHeight - 30, 30, currentHeight);

      // 目標偏差値バー
      const targetHeight = (data.targetDeviation / maxDeviation) * (canvas.height - 60);
      ctx.fillStyle = '#e74c3c';
      ctx.fillRect(x + 15, canvas.height - targetHeight - 30, 30, targetHeight);

      // ラベル
      ctx.fillStyle = '#2c3e50';
      ctx.font = '12px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(subject, x, canvas.height - 10);
      ctx.fillText(data.currentDeviation.toString(), x - 15, canvas.height - currentHeight - 35);
      ctx.fillText(data.targetDeviation.toString(), x + 15, canvas.height - targetHeight - 35);
    });

    // 凡例
    ctx.fillStyle = '#3498db';
    ctx.fillRect(20, 20, 15, 15);
    ctx.fillStyle = '#2c3e50';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'left';
    ctx.fillText('現在偏差値', 40, 32);

    ctx.fillStyle = '#e74c3c';
    ctx.fillRect(120, 20, 15, 15);
    ctx.fillStyle = '#2c3e50';
    ctx.fillText('合格ライン', 140, 32);
  }

  // 成績推移チャート描画
  function drawProgressChart(result) {
    const canvas = container.querySelector('#progress-chart');
    const ctx = canvas.getContext('2d');

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (result.progressData.length === 0) return;

    const sortedData = result.progressData.sort((a, b) => new Date(a.date) - new Date(b.date));
    const pointWidth = canvas.width / (sortedData.length + 1);
    const maxDeviation = 80;
    const minDeviation = 20;

    ctx.strokeStyle = '#3498db';
    ctx.lineWidth = 2;
    ctx.beginPath();

    sortedData.forEach((point, index) => {
      const x = (index + 1) * pointWidth;
      const y = canvas.height - 30 - ((point.deviation - minDeviation) / (maxDeviation - minDeviation)) * (canvas.height - 60);

      if (index === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }

      // データポイント
      ctx.fillStyle = '#3498db';
      ctx.beginPath();
      ctx.arc(x, y, 4, 0, 2 * Math.PI);
      ctx.fill();

      // 日付ラベル
      ctx.fillStyle = '#2c3e50';
      ctx.font = '10px sans-serif';
      ctx.textAlign = 'center';
      const date = new Date(point.date).toLocaleDateString();
      ctx.fillText(date, x, canvas.height - 10);
    });

    ctx.stroke();

    // 目標ライン
    const targetY = canvas.height - 30 - ((result.targetDeviation - minDeviation) / (maxDeviation - minDeviation)) * (canvas.height - 60);
    ctx.strokeStyle = '#e74c3c';
    ctx.setLineDash([5, 5]);
    ctx.beginPath();
    ctx.moveTo(0, targetY);
    ctx.lineTo(canvas.width, targetY);
    ctx.stroke();
    ctx.setLineDash([]);
  }

  // イベントリスナー設定
  container.querySelector('#btn-diagnose').addEventListener('click', executeDiagnosis);

  // 初期化
  loadInitialData();
}

function(container, apiUrl, tables) {
  let currentExams = [];
  let currentView = 'list';
  let currentDate = new Date();
  let currentNotificationExamId = null;

  // 1. テーブル再描画関数を定義
  function renderRows(rows) {
    const tbody = container.querySelector('#exam-tbody');
    const noDataMessage = container.querySelector('#no-data-message');

    if (!rows || rows.length === 0) {
      tbody.innerHTML = '';
      noDataMessage.classList.remove('hidden');
      return;
    }

    noDataMessage.classList.add('hidden');
    tbody.innerHTML = rows.map(r => {
      const examDate = new Date(r.実施日 || '');
      const deadlineDate = new Date(r.申込締切日 || '');
      const resultDate = new Date(r.結果発表予定日 || '');
      const today = new Date();

      // 申込状況の判定
      let status = '未申込';
      let statusClass = 'status-pending';
      if (deadlineDate < today) {
        status = '申込期限切れ';
        statusClass = 'status-expired';
      }

      // 申込済みマークの表示（サンプルデータでは申込可能フラグで判定）
      const isApplied = r.申込可能フラグ === false;
      if (isApplied) {
        status = '申込済み';
        statusClass = 'status-applied';
      }

      return `
        <tr data-id="${r.模試日程ID || r.id || ''}">
          <td>
            <div style="font-weight: 500;">${r.模試名 || ''}</div>
            <div style="font-size: 12px; color: var(--text-muted);">${r.模試種別 || ''}</div>
          </td>
          <td>${r.実施機関名 || ''}</td>
          <td>${r.対象学年 || ''}</td>
          <td>${examDate.getTime() ? examDate.toLocaleDateString('ja-JP') : ''}</td>
          <td>${deadlineDate.getTime() ? deadlineDate.toLocaleDateString('ja-JP') : ''}</td>
          <td>${resultDate.getTime() ? resultDate.toLocaleDateString('ja-JP') : ''}</td>
          <td>
            <span class="status-badge ${statusClass}" style="padding: 2px 8px; border-radius: 12px; font-size: 11px; font-weight: 500;">
              ${status}
            </span>
          </td>
          <td>${r.受験料 ? `¥${r.受験料.toLocaleString()}` : ''}</td>
          <td>
            <button class="action-btn secondary detail-btn" data-id="${r.模試日程ID || r.id || ''}" style="margin-right: 4px;">詳細</button>
            ${r.申込URL ? `<button class="action-btn secondary apply-btn" data-url="${r.申込URL}">申込</button>` : ''}
            <button class="action-btn secondary notify-btn" data-id="${r.模試日程ID || r.id || ''}" style="margin-left: 4px;">通知設定</button>
          </td>
        </tr>
      `;
    }).join('');

    // ステータスバッジのスタイル適用
    const style = document.createElement('style');
    style.textContent = `
      .status-applied { background: #d4edda; color: #155724; }
      .status-pending { background: #fff3cd; color: #856404; }
      .status-expired { background: #f8d7da; color: #721c24; }
    `;
    if (!document.querySelector('#status-styles')) {
      style.id = 'status-styles';
      document.head.appendChild(style);
    }
  }

  // カレンダー表示関数
  function renderCalendar(year, month) {
    const calendarGrid = container.querySelector('#calendar-grid');
    const calendarTitle = container.querySelector('#calendar-title');

    calendarTitle.textContent = `${year}年${month + 1}月`;

    const firstDay = new Date(year, month, 1);
    const lastDay = new Date(year, month + 1, 0);
    const startDate = new Date(firstDay);
    startDate.setDate(startDate.getDate() - firstDay.getDay());

    const days = ['日', '月', '火', '水', '木', '金', '土'];
    let html = days.map(day => `<div style="padding: 8px; background: var(--bg-card); font-weight: 500; text-align: center; color: var(--text);">${day}</div>`).join('');

    for (let i = 0; i < 42; i++) {
      const date = new Date(startDate);
      date.setDate(startDate.getDate() + i);

      const isCurrentMonth = date.getMonth() === month;
      const dateStr = date.toISOString().split('T')[0];
      const examsOnDate = currentExams.filter(exam => {
        const examDate = new Date(exam.実施日 || '');
        return examDate.toISOString().split('T')[0] === dateStr;
      });

      html += `
        <div style="min-height: 80px; padding: 4px; background: var(--bg-card); border: 1px solid var(--border); ${!isCurrentMonth ? 'opacity: 0.5;' : ''}">
          <div style="font-size: 12px; color: var(--text-muted); margin-bottom: 2px;">${date.getDate()}</div>
          ${examsOnDate.map(exam => `
            <div style="font-size: 10px; padding: 1px 3px; margin-bottom: 1px; background: #e3f2fd; color: #1565c0; border-radius: 2px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">
              ${exam.模試名 || ''}
            </div>
          `).join('')}
        </div>
      `;
    }

    calendarGrid.innerHTML = html;
  }

  // フィルター適用関数
  function applyFilters() {
    const startDate = container.querySelector('#filter-start-date').value;
    const endDate = container.querySelector('#filter-end-date').value;
    const school = container.querySelector('#filter-school').value;
    const subject = container.querySelector('#filter-subject').value;
    const status = container.querySelector('#filter-status').value;
    const searchTerm = container.querySelector('#input-search').value.toLowerCase();

    // 日付範囲の妥当性チェック
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      showError('終了日は開始日より後の日付を入力してください');
      return;
    }

    hideError();

    window.aivicApi.list(0).then(rows => {
      if (!rows) {
        showError('データの取得に失敗しました');
        return;
      }

      let filtered = rows.filter(r => {
        // 日付フィルター
        if (startDate || endDate) {
          const examDate = new Date(r.実施日 || '');
          if (startDate && examDate < new Date(startDate)) return false;
          if (endDate && examDate > new Date(endDate)) return false;
        }

        // 予備校フィルター
        if (school && r.実施機関名 !== school) return false;

        // 科目フィルター（模試種別で判定）
        if (subject && !r.模試種別?.includes(subject)) return false;

        // 申込状況フィルター
        if (status) {
          const deadlineDate = new Date(r.申込締切日 || '');
          const today = new Date();
          const isApplied = r.申込可能フラグ === false;

          if (status === '申込済み' && !isApplied) return false;
          if (status === '未申込' && (isApplied || deadlineDate < today)) return false;
          if (status === '申込期限切れ && (isApplied || deadlineDate >= today)) return false;
        }

        // 検索語フィルター
        if (searchTerm && !r.模試名?.toLowerCase().includes(searchTerm)) return false;

        return true;
      });

      currentExams = filtered;

      if (currentView === 'list') {
        renderRows(filtered);
      } else {
        renderCalendar(currentDate.getFullYear(), currentDate.getMonth());
      }
    }).catch(() => {
      showError('ネットワークエラーが発生しました');
    });
  }

  // エラー表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
  }

  function hideError() {
    container.querySelector('#error-message').classList.add('hidden');
  }

  // CSVエクスポート関数
  function exportCSV() {
    window.aivicApi.list(0).then(rows => {
      if (!rows || rows.length === 0) {
        showError('エクスポートするデータがありません');
        return;
      }

      const headers = ['模試名', '実施機関名', '対象学年', '模試種別', '実施日', '申込締切日', '結果発表予定日', '受験料', '会場情報'];
      const csvContent = '\uFEFF' + [
        headers.join(','),
        ...rows.map(r => [
          `"${r.模試名 || ''}"`,
          `"${r.実施機関名 || ''}"`,
          `"${r.対象学年 || ''}"`,
          `"${r.模試種別 || ''}"`,
          `"${r.実施日 || ''}"`,
          `"${r.申込締切日 || ''}"`,
          `"${r.結果発表予定日 || ''}"`,
          `"${r.受験料 || ''}"`,
          `"${r.会場情報 || ''}"`
        ].join(','))
      ].join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = `模試日程_${new Date().toISOString().split('T')[0]}.csv`;
      link.click();
    });
  }

  // 2. 初期データを即座に描画
  currentExams = tables[0]?.records || [];
  renderRows(currentExams);

  // 3. 検索ボタンのイベントリスナー
  container.querySelector('#btn-search').addEventListener('click', applyFilters);

  // フィルターリセット
  container.querySelector('#btn-reset-filter').addEventListener('click', () => {
    container.querySelector('#filter-start-date').value = '';
    container.querySelector('#filter-end-date').value = '';
    container.querySelector('#filter-school').value = '';
    container.querySelector('#filter-subject').value = '';
    container.querySelector('#filter-status').value = '';
    container.querySelector('#input-search').value = '';

    window.aivicApi.list(0).then(rows => {
      currentExams = rows || [];
      if (currentView === 'list') {
        renderRows(currentExams);
      } else {
        renderCalendar(currentDate.getFullYear(), currentDate.getMonth());
      }
    });
  });

  // カレンダー表示切替
  container.querySelector('#btn-calendar-view').addEventListener('click', () => {
    const listView = container.querySelector('#list-view');
    const calendarView = container.querySelector('#calendar-view');
    const btn = container.querySelector('#btn-calendar-view');

    if (currentView === 'list') {
      currentView = 'calendar';
      listView.classList.add('hidden');
      calendarView.classList.remove('hidden');
      btn.textContent = 'リスト表示切替';
      renderCalendar(currentDate.getFullYear(), currentDate.getMonth());
    } else {
      currentView = 'list';
      listView.classList.remove('hidden');
      calendarView.classList.add('hidden');
      btn.textContent = 'カレンダー表示切替';
      renderRows(currentExams);
    }
  });

  // カレンダーナビゲーション
  container.querySelector('#btn-prev-month').addEventListener('click', () => {
    currentDate.setMonth(currentDate.getMonth() - 1);
    renderCalendar(currentDate.getFullYear(), currentDate.getMonth());
  });

  container.querySelector('#btn-next-month').addEventListener('click', () => {
    currentDate.setMonth(currentDate.getMonth() + 1);
    renderCalendar(currentDate.getFullYear(), currentDate.getMonth());
  });

  // CSVエクスポート
  container.querySelector('#btn-export-csv').addEventListener('click', exportCSV);

  // 5. 行レベル操作のイベントデリゲーション
  container.addEventListener('click', async (e) => {
    // 詳細ボタン
    const detailBtn = e.target.closest('.detail-btn');
    if (detailBtn) {
      const examId = detailBtn.dataset.id;
      const exam = currentExams.find(r => (r.模試日程ID || r.id) === examId);
      if (exam) {
        alert(`模試詳細\n\n模試名: ${exam.模試名}\n実施機関: ${exam.実施機関名}\n実施日: ${new Date(exam.実施日).toLocaleDateString('ja-JP')}\n会場: ${exam.会場情報 || '未定'}\n出題範囲: ${exam.出題範囲 || '詳細は公式サイトをご確認ください'}`);
      }
      return;
    }

    // 申込ボタン
    const applyBtn = e.target.closest('.apply-btn');
    if (applyBtn) {
      const url = applyBtn.dataset.url;
      if (url && url !== 'undefined') {
        try {
          window.open(url, '_blank');
        } catch (error) {
          showError('申込サイトへのリンクが無効です');
        }
      } else {
        showError('申込リンクが設定されていません');
      }
      return;
    }

    // 通知設定ボタン
    const notifyBtn = e.target.closest('.notify-btn');
    if (notifyBtn) {
      currentNotificationExamId = notifyBtn.dataset.id;
      container.querySelector('#notification-modal').classList.remove('hidden');
      return;
    }
  });

  // 通知設定モーダルの処理
  container.querySelector('#btn-cancel-notification').addEventListener('click', () => {
    container.querySelector('#notification-modal').classList.add('hidden');
    currentNotificationExamId = null;
  });

  container.querySelector('#btn-save-notification').addEventListener('click', () => {
    const notify3Days = container.querySelector('#notify-3days').checked;
    const notify1Day = container.querySelector('#notify-1day').checked;
    const notifyResult = container.querySelector('#notify-result').checked;
    const notifyTime = container.querySelector('#notify-time').value;

    // 通知設定を保存（実際の実装では通知設定テーブルに保存）
    console.log('通知設定保存:', {
      examId: currentNotificationExamId,
      notify3Days,
      notify1Day,
      notifyResult,
      notifyTime
    });

    alert('通知設定が保存されました');
    container.querySelector('#notification-modal').classList.add('hidden');
    currentNotificationExamId = null;
  });

  // Enterキーで検索
  container.querySelector('#input-search').addEventListener('keypress', (e) => {
    if (e.key === 'Enter') {
      applyFilters();
    }
  });

  // 初期データ読み込み
  window.aivicApi.list(0).then(rows => {
    if (rows) {
      currentExams = rows;
      renderRows(rows);
    }
  }).catch(() => {
    showError('データの読み込みに失敗しました');
  });
}

function(container, apiUrl, tables) {
  // 統合処理の状態管理
  let integrationInProgress = false;
  let progressInterval = null;

  // 統合履歴の再描画関数
  function renderHistoryRows(rows) {
    const tbody = container.querySelector("#history-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.id}">
        <td>${r.統合処理日時 || ""}</td>
        <td>${r.統合処理種別 || ""}</td>
        <td>${r.統合対象期間開始日 || ""} ～ ${r.統合対象期間終了日 || ""}</td>
        <td><span class="status-badge ${getStatusClass(r.統合処理ステータス)}">${r.統合処理ステータス || ""}</span></td>
        <td>${r.統合後データ件数 || 0}件</td>
        <td>${r.処理時間秒 || 0}秒</td>
        <td>${r.実行者種別 || ""}</td>
      </tr>
    `).join("");
  }

  function getStatusClass(status) {
    switch(status) {
      case "完了": return "success";
      case "処理中": return "processing";
      case "エラー": return "error";
      default: return "warning";
    }
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      const historyRows = await window.aivicApi.list(12); // 成績データ統合履歴
      if (historyRows) {
        renderHistoryRows(historyRows);
      }
    } catch (error) {
      console.error("初期データ読み込みエラー:", error);
    }
  }

  // データソース選択チェック
  function getSelectedDataSources() {
    const checkboxes = container.querySelectorAll(".data-source-checkbox:checked");
    return Array.from(checkboxes).map(cb => cb.value);
  }

  // 統合データ取得
  container.querySelector("#btn-get-data").addEventListener("click", async () => {
    const startDate = container.querySelector("#start-date").value;
    const endDate = container.querySelector("#end-date").value;

    if (!startDate || !endDate) {
      alert("期間を指定してください");
      return;
    }

    if (new Date(startDate) > new Date(endDate)) {
      alert("開始日は終了日より前の日付を指定してください");
      return;
    }

    // データ取得処理のシミュレーション
    const progressSection = container.querySelector("#progress-section");
    progressSection.classList.remove("hidden");

    let progress = 0;
    const interval = setInterval(() => {
      progress += 10;
      container.querySelector("#progress-bar").style.width = progress + "%";
      container.querySelector("#progress-percent").textContent = progress + "%";
      container.querySelector("#progress-message").textContent = `データ取得中... ${progress}%`;

      if (progress >= 100) {
        clearInterval(interval);
        container.querySelector("#progress-message").textContent = "データ取得が完了しました";
        setTimeout(() => {
          progressSection.classList.add("hidden");
        }, 2000);
      }
    }, 200);
  });

  // 統合実行
  container.querySelector("#btn-execute-integration").addEventListener("click", async () => {
    const selectedSources = getSelectedDataSources();
    const startDate = container.querySelector("#start-date").value;
    const endDate = container.querySelector("#end-date").value;

    if (selectedSources.length === 0) {
      alert("データソースを選択してください");
      return;
    }

    if (!startDate || !endDate) {
      alert("統合対象期間を指定してください");
      return;
    }

    integrationInProgress = true;
    container.querySelector("#btn-execute-integration").disabled = true;
    container.querySelector("#btn-cancel-integration").disabled = false;

    const progressSection = container.querySelector("#progress-section");
    progressSection.classList.remove("hidden");

    // 統合履歴に記録
    const integrationRecord = {
      統合処理日時: new Date().toLocaleString(),
      統合処理種別: "全件統合",
      統合対象期間開始日: startDate,
      統合対象期間終了日: endDate,
      統合処理ステータス: "処理中",
      予備校データ件数: 0,
      模試データ件数: 0,
      統合後データ件数: 0,
      処理時間秒: 0,
      実行者種別: "保護者手動"
    };

    const saved = await window.aivicApi.save(12, integrationRecord);

    // 進捗シミュレーション
    let progress = 0;
    progressInterval = setInterval(async () => {
      progress += Math.random() * 15;
      if (progress > 100) progress = 100;

      container.querySelector("#progress-bar").style.width = progress + "%";
      container.querySelector("#progress-percent").textContent = Math.floor(progress) + "%";

      if (progress < 30) {
        container.querySelector("#progress-message").textContent = "データソースに接続中...";
      } else if (progress < 60) {
        container.querySelector("#progress-message").textContent = "データを取得中...";
      } else if (progress < 90) {
        container.querySelector("#progress-message").textContent = "データを統合中...";
      } else if (progress < 100) {
        container.querySelector("#progress-message").textContent = "統合処理を完了中...";
      } else {
        container.querySelector("#progress-message").textContent = "統合処理が完了しました";
        clearInterval(progressInterval);

        // 統合完了処理
        integrationInProgress = false;
        container.querySelector("#btn-execute-integration").disabled = false;
        container.querySelector("#btn-cancel-integration").disabled = true;

        // 完了通知表示
        const notification = container.querySelector("#completion-notification");
        notification.classList.remove("hidden");
        container.querySelector("#completion-message").textContent = "データ統合が正常に完了しました";
        container.querySelector("#completion-stats").textContent = `統合データ件数: ${Math.floor(Math.random() * 100) + 50}件, 処理時間: ${Math.floor(Math.random() * 30) + 10}秒`;

        // 統合履歴更新
        if (saved) {
          await window.aivicApi.update(12, saved.id, {
            統合処理ステータス: "完了",
            統合後データ件数: Math.floor(Math.random() * 100) + 50,
            処理時間秒: Math.floor(Math.random() * 30) + 10
          });
          loadInitialData();
        }

        setTimeout(() => {
          progressSection.classList.add("hidden");
          notification.classList.add("hidden");
        }, 5000);
      }
    }, 300);
  });

  // 統合中断
  container.querySelector("#btn-cancel-integration").addEventListener("click", () => {
    if (progressInterval) {
      clearInterval(progressInterval);
      progressInterval = null;
    }
    integrationInProgress = false;
    container.querySelector("#btn-execute-integration").disabled = false;
    container.querySelector("#btn-cancel-integration").disabled = true;
    container.querySelector("#progress-section").classList.add("hidden");

    // エラー詳細表示
    const errorDetails = container.querySelector("#error-details");
    errorDetails.classList.remove("hidden");
    container.querySelector("#error-message").textContent = "統合処理がユーザーによって中断されました";
    container.querySelector("#error-timestamp").textContent = "中断日時: " + new Date().toLocaleString();
  });

  // 重複チェック実行
  container.querySelector("#btn-duplicate-check").addEventListener("click", async () => {
    const results = container.querySelector("#duplicate-results");
    results.classList.remove("hidden");

    const tbody = container.querySelector("#duplicate-tbody");
    tbody.innerHTML = `
      <tr>
        <td>予備校成績データ</td>
        <td>3件</td>
        <td>同一テスト日・科目の重複</td>
        <td><button class="action-btn secondary">統合</button></td>
      </tr>
      <tr>
        <td>模試結果データ</td>
        <td>1件</td>
        <td>受験生ID重複</td>
        <td><button class="action-btn secondary">統合</button></td>
      </tr>
      <tr>
        <td>科目別成績データ</td>
        <td>0件</td>
        <td>重複なし</td>
        <td>-</td>
      </tr>
    `;
  });

  // 手動データ補正
  container.querySelector("#btn-apply-correction").addEventListener("click", () => {
    const type = container.querySelector("#correction-type").value;
    const value = container.querySelector("#correction-value").value;
    const reason = container.querySelector("#correction-reason").value;

    if (!type) {
      alert("補正対象を選択してください");
      return;
    }

    if (!value) {
      alert("補正値を入力してください");
      return;
    }

    // バリデーション
    if (type === "score" && (isNaN(value) || value < 0 || value > 100)) {
      alert("0-100の範囲で入力してください");
      return;
    }

    if (type === "subject" && /^\d+$/.test(value)) {
      alert("有効な科目名を入力してください");
      return;
    }

    if (type === "date" && !Date.parse(value)) {
      alert("正しい日付形式で入力してください");
      return;
    }

    alert("データ補正を適用しました");

    // フォームリセット
    container.querySelector("#correction-type").value = "";
    container.querySelector("#correction-value").value = "";
    container.querySelector("#correction-reason").value = "";
  });

  // 品質チェック実行
  container.querySelector("#btn-quality-check").addEventListener("click", () => {
    const results = container.querySelector("#quality-results");
    results.classList.remove("hidden");

    const tbody = container.querySelector("#quality-tbody");
    tbody.innerHTML = `
      <tr>
        <td>データ形式チェック</td>
        <td><span class="status-badge success">正常</span></td>
        <td>245件</td>
        <td>3件</td>
        <td>0件</td>
        <td>日付形式の軽微な不整合</td>
      </tr>
      <tr>
        <td>必須項目チェック</td>
        <td><span class="status-badge success">正常</span></td>
        <td>248件</td>
        <td>0件</td>
        <td>0件</td>
        <td>-</td>
      </tr>
      <tr>
        <td>数値範囲チェック</td>
        <td><span class="status-badge warning">警告</span></td>
        <td>240件</td>
        <td>8件</td>
        <td>0件</td>
        <td>偏差値が範囲外の値</td>
      </tr>
      <tr>
        <td>重複データチェック</td>
        <td><span class="status-badge success">正常</span></td>
        <td>244件</td>
        <td>4件</td>
        <td>0件</td>
        <td>軽微な重複あり</td>
      </tr>
    `;
  });

  // CSVエクスポート
  container.querySelector("#btn-export-history").addEventListener("click", async () => {
    try {
      const rows = await window.aivicApi.list(12);
      if (!rows) {
        alert("エクスポートするデータがありません");
        return;
      }

      const headers = ["実行日時", "統合種別", "対象期間開始日", "対象期間終了日", "処理ステータス", "統合件数", "処理時間", "実行者"];
      const csvContent = "\uFEFF" + [
        headers.join(","),
        ...rows.map(row => [
          row.統合処理日時 || "",
          row.統合処理種別 || "",
          row.統合対象期間開始日 || "",
          row.統合対象期間終了日 || "",
          row.統合処理ステータス || "",
          row.統合後データ件数 || 0,
          row.処理時間秒 || 0,
          row.実行者種別 || ""
        ].join(","))
      ].join("\n");

      const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
      const link = document.createElement("a");
      link.href = URL.createObjectURL(blob);
      link.download = "integration_history.csv";
      link.click();
    } catch (error) {
      alert("CSVエクスポートに失敗しました");
    }
  });

  // 初期データ読み込み
  loadInitialData();
}

function(container, apiUrl, tables) {
  let currentSettings = {};

  // 通知履歴テーブル再描画関数
  function renderNotificationHistory(rows) {
    const tbody = container.querySelector("#notification-history-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.通知履歴ID || r.id}">
        <td>${r.送信日時 ? new Date(r.送信日時).toLocaleString() : ""}</td>
        <td>${r.通知種別 || ""}</td>
        <td>${r.通知タイトル || ""}</td>
        <td>${r.通知方法 || ""}</td>
        <td>
          <span style="padding: 2px 8px; border-radius: 4px; font-size: 12px; 
                       background: ${r.送信ステータス === '送信完了' ? '#e8f5e8' : r.送信ステータス === '送信失敗' ? '#ffe8e8' : '#fff3e0'}; 
                       color: var(--text);">
            ${r.送信ステータス || ""}
          </span>
        </td>
        <td>
          <span style="padding: 2px 8px; border-radius: 4px; font-size: 12px; 
                       background: ${r.既読フラグ ? '#e8f5e8' : '#ffe8e8'}; 
                       color: var(--text);">
            ${r.既読フラグ ? '既読' : '未読'}
          </span>
        </td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${r.通知履歴ID || r.id}">詳細</button>
          <button class="action-btn secondary delete-btn" data-id="${r.通知履歴ID || r.id}">削除</button>
        </td>
      </tr>
    `).join("");
  }

  // 設定値を画面に反映
  function loadSettings() {
    window.aivicApi.list(24).then(settings => {
      if (settings && settings.length > 0) {
        const setting = settings[0];
        currentSettings = setting;

        // 通知種別設定
        const gradeUpdate = container.querySelector("#notification-grade-update");
        const mockExam = container.querySelector("#notification-mock-exam");
        const deviationChange = container.querySelector("#notification-deviation-change");
        const admissionProbability = container.querySelector("#notification-admission-probability");
        const mockSchedule = container.querySelector("#notification-mock-schedule");

        if (setting.通知種別コード === '成績更新') gradeUpdate.checked = setting.通知有効フラグ;
        if (setting.通知種別コード === '模試結果') mockExam.checked = setting.通知有効フラグ;
        if (setting.通知種別コード === '偏差値変動') deviationChange.checked = setting.通知有効フラグ;
        if (setting.通知種別コード === '合格可能性変動') admissionProbability.checked = setting.通知有効フラグ;
        if (setting.通知種別コード === '模試日程リマインダー') mockSchedule.checked = setting.通知有効フラグ;

        // 通知タイミング
        const timing = container.querySelector("#notification-timing");
        if (setting.通知タイミング === '即座') timing.value = 'immediate';
        else if (setting.通知タイミング === '日次') timing.value = 'daily';
        else if (setting.通知タイミング === '週次') timing.value = 'weekly';

        // 通知方法
        const methodApp = container.querySelector("#notification-method-app");
        const methodEmail = container.querySelector("#notification-method-email");
        const methodSms = container.querySelector("#notification-method-sms");

        if (setting.通知方法 && setting.通知方法.includes('アプリ内通知')) methodApp.checked = true;
        if (setting.通知方法 && setting.通知方法.includes('メール')) methodEmail.checked = true;
        if (setting.通知方法 && setting.通知方法.includes('SMS')) methodSms.checked = true;

        // 閾値設定
        if (setting.偏差値変動閾値) {
          container.querySelector("#deviation-threshold").value = setting.偏差値変動閾値;
        }
        if (setting.合格可能性変動閾値) {
          container.querySelector("#probability-threshold").value = setting.合格可能性変動閾値;
        }

        // 通知時間
        if (setting.通知時刻) {
          container.querySelector("#notification-time").value = setting.通知時刻;
        }
      }
    });
  }

  // 初期データ読み込み
  window.aivicApi.list(25).then(renderNotificationHistory);
  loadSettings();

  // 検索機能
  container.querySelector("#btn-search").addEventListener("click", () => {
    const keyword = container.querySelector("#input-search").value.toLowerCase();
    window.aivicApi.list(25).then(rows => {
      const filtered = rows.filter(r => 
        JSON.stringify(r).toLowerCase().includes(keyword)
      );
      renderNotificationHistory(filtered);
    });
  });

  // 設定保存
  container.querySelector("#btn-save-settings").addEventListener("click", async () => {
    // バリデーション
    const deviationThreshold = container.querySelector("#deviation-threshold").value;
    const probabilityThreshold = container.querySelector("#probability-threshold").value;
    const notificationTime = container.querySelector("#notification-time").value;

    // 偏差値閾値の文字入力チェック
    if (deviationThreshold && isNaN(deviationThreshold)) {
      alert("偏差値変動閾値には数値を入力してください");
      return;
    }

    // 合格可能性閾値の負数チェック
    if (probabilityThreshold && parseFloat(probabilityThreshold) < 0) {
      alert("合格可能性変動閾値には0以上の数値を入力してください");
      return;
    }

    // 通知方法未選択チェック
    const methodApp = container.querySelector("#notification-method-app").checked;
    const methodEmail = container.querySelector("#notification-method-email").checked;
    const methodSms = container.querySelector("#notification-method-sms").checked;

    if (!methodApp && !methodEmail && !methodSms) {
      alert("通知方法を選択してください");
      return;
    }

    // 時間形式チェック
    if (notificationTime && !/^([01]?[0-9]|2[0-3]):[0-5][0-9]$/.test(notificationTime)) {
      alert("正しい時間形式（HH:MM）で入力してください");
      return;
    }

    // 通知方法の配列作成
    const methods = [];
    if (methodApp) methods.push('アプリ内通知');
    if (methodEmail) methods.push('メール');
    if (methodSms) methods.push('SMS');

    // 通知タイミング変換
    const timing = container.querySelector("#notification-timing").value;
    let timingText = '';
    if (timing === 'immediate') timingText = '即座';
    else if (timing === 'daily') timingText = '日次';
    else if (timing === 'weekly') timingText = '週次';

    const settingData = {
      受験生ID: 'test-student-id',
      保護者ID: 'test-parent-id',
      通知種別コード: '成績更新',
      通知種別名: '成績更新通知',
      通知方法: methods.join(','),
      通知有効フラグ: container.querySelector("#notification-grade-update").checked,
      通知タイミング: timingText,
      通知時刻: notificationTime,
      偏差値変動閾値: deviationThreshold ? parseInt(deviationThreshold) : null,
      合格可能性変動閾値: probabilityThreshold ? parseInt(probabilityThreshold) : null,
      通知優先度: 2,
      作成日時: new Date().toISOString(),
      更新日時: new Date().toISOString(),
      作成者ID: 'system',
      更新者ID: 'system'
    };

    const saved = await window.aivicApi.save(24, settingData);
    if (saved) {
      alert("設定を保存しました");
      loadSettings();
    }
  });

  // CSVエクスポート
  container.querySelector("#btn-export-csv").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(25);
    if (!rows) return;

    const headers = ['送信日時', '通知種別', 'タイトル', '通知内容', '通知方法', '送信ステータス', '既読状況'];
    const csvContent = '\uFEFF' + [
      headers.join(','),
      ...rows.map(r => [
        r.送信日時 ? new Date(r.送信日時).toLocaleString() : '',
        r.通知種別 || '',
        `"${(r.通知タイトル || '').replace(/"/g, '""')}"`,
        `"${(r.通知内容 || '').replace(/"/g, '""')}"`,
        r.通知方法 || '',
        r.送信ステータス || '',
        r.既読フラグ ? '既読' : '未読'
      ].join(','))
    ].join('\n');

    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = '通知履歴.csv';
    link.click();
  });

  // 通知詳細表示
  function showNotificationDetail(id) {
    window.aivicApi.list(25).then(rows => {
      const notification = rows.find(r => (r.通知履歴ID || r.id) === id);
      if (!notification) return;

      const modal = container.querySelector("#notification-detail-modal");
      const content = container.querySelector("#notification-detail-content");

      content.innerHTML = `
        <div style="margin-bottom: 15px;">
          <strong>送信日時:</strong> ${notification.送信日時 ? new Date(notification.送信日時).toLocaleString() : ''}
        </div>
        <div style="margin-bottom: 15px;">
          <strong>通知種別:</strong> ${notification.通知種別 || ''}
        </div>
        <div style="margin-bottom: 15px;">
          <strong>タイトル:</strong> ${notification.通知タイトル || ''}
        </div>
        <div style="margin-bottom: 15px;">
          <strong>通知内容:</strong><br>
          <div style="background: var(--bg-card); padding: 10px; border-radius: 4px; margin-top: 5px;">
            ${notification.通知内容 || ''}
          </div>
        </div>
        <div style="margin-bottom: 15px;">
          <strong>通知方法:</strong> ${notification.通知方法 || ''}
        </div>
        <div style="margin-bottom: 15px;">
          <strong>送信ステータス:</strong> 
          <span style="padding: 2px 8px; border-radius: 4px; font-size: 12px; 
                       background: ${notification.送信ステータス === '送信完了' ? '#e8f5e8' : notification.送信ステータス === '送信失敗' ? '#ffe8e8' : '#fff3e0'}; 
                       color: var(--text);">
            ${notification.送信ステータス || ""}
          </span>
        </div>
        <div style="margin-bottom: 15px;">
          <strong>既読状況:</strong> 
          <span style="padding: 2px 8px; border-radius: 4px; font-size: 12px; 
                       background: ${notification.既読フラグ ? '#e8f5e8' : '#ffe8e8'}; 
                       color: var(--text);">
            ${notification.既読フラグ ? '既読' : '未読'}
          </span>
        </div>
        ${notification.既読日時 ? `
        <div style="margin-bottom: 15px;">
          <strong>既読日時:</strong> ${new Date(notification.既読日時).toLocaleString()}
        </div>
        ` : ''}
      `;

      modal.classList.remove('hidden');
    });
  }

  // モーダル閉じる
  container.querySelector("#btn-close-modal").addEventListener("click", () => {
    container.querySelector("#notification-detail-modal").classList.add('hidden');
  });

  // イベントデリゲーション（詳細・削除）
  container.addEventListener("click", async (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      showNotificationDetail(detailBtn.dataset.id);
      return;
    }

    const deleteBtn = e.target.closest(".delete-btn");
    if (deleteBtn) {
      if (!confirm("この通知履歴を削除しますか？")) return;
      await window.aivicApi.delete(25, deleteBtn.dataset.id);
      window.aivicApi.list(25).then(renderNotificationHistory);
      return;
    }
  });
}

