  function updateMissingItems(data) {
    const alertSection = container.querySelector('#alert-section');
    const missingList = container.querySelector('#missing-items');
    const missingItems = [];

    if (!data.basicInfo.registered) {
      missingItems.push('基本情報の登録');
    }
    if (data.schools.length === 0) {
      missingItems.push('志望校の登録');
    }
    if (data.exams.length === 0) {
      missingItems.push('模試結果の登録');
    }
    if (data.prepSchools.length === 0) {
      missingItems.push('予備校データ連携の設定');
