function(container, apiUrl, tables) {
  let allNotifications = [];
  let filteredNotifications = [];

  // 通知一覧を描画する関数
  function renderNotifications(notifications) {
    const listContainer = container.querySelector('#notification-list');
    const noNotificationsDiv = container.querySelector('#no-notifications');

    if (!notifications || notifications.length === 0) {
      listContainer.innerHTML = '';
      noNotificationsDiv.style.display = 'block';
      updateUnreadBadge(0);
      return;
    }

    noNotificationsDiv.style.display = 'none';

    listContainer.innerHTML = notifications.map(notification => {
      const isUnread = !notification.既読フラグ;
      const categoryClass = `category-${notification.通知種別 || 'システム'}`;

      return `
        <div class="notification-item ${isUnread ? 'unread' : ''}" data-id="${notification.通知履歴ID}">
          <div class="notification-header">
            <h4 class="notification-title">${notification.通知タイトル || ''}</h4>
            <div class="notification-meta">
              <span class="notification-category ${categoryClass}">${notification.通知種別 || 'システム'}</span>
              <span>${formatDate(notification.送信日時)}</span>
              ${isUnread ? '<div class="unread-mark"></div>' : ''}
            </div>
          </div>
          <div class="notification-content">
            ${notification.通知内容 || ''}
          </div>
          <div class="notification-actions">
            ${notification.関連データ種別 === '成績データ' ? `<a href="#" class="notification-link" data-action="grade-detail" data-id="${notification.関連データID}">成績詳細</a>` : ''}
            ${notification.関連データ種別 === '模試結果' ? `<a href="#" class="notification-link" data-action="exam-result" data-id="${notification.関連データID}">模試結果</a>` : ''}
            <button class="notification-delete" data-id="${notification.通知履歴ID}">削除</button>
          </div>
        </div>
      `;
    }).join('');

    // 未読件数を更新
    const unreadCount = notifications.filter(n => !n.既読フラグ).length;
    updateUnreadBadge(unreadCount);
  }

  // 未読バッジを更新
  function updateUnreadBadge(count) {
    const badge = container.querySelector('#unread-badge');
    if (count > 0) {
      badge.textContent = count;
      badge.style.display = 'inline-block';
    } else {
      badge.style.display = 'none';
    }
  }

  // 日付フォーマット
  function formatDate(dateString) {
    if (!dateString) return '';
    const date = new Date(dateString);
    return date.toLocaleDateString('ja-JP') + ' ' + date.toLocaleTimeString('ja-JP', {hour: '2-digit', minute: '2-digit'});
  }

  // エラー表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    const errorText = container.querySelector('#error-text');
    errorText.textContent = message;
    errorDiv.style.display = 'block';
    setTimeout(() => {
      errorDiv.style.display = 'none';
    }, 5000);
  }

  // フィルター適用
  function applyFilters() {
    const category = container.querySelector('#filter-category').value;
    const status = container.querySelector('#filter-status').value;
    const startDate = container.querySelector('#filter-start-date').value;
    const endDate = container.querySelector('#filter-end-date').value;

    // 日付範囲の妥当性チェック
    if (startDate && endDate && new Date(startDate) > new Date(endDate)) {
      showError('終了日は開始日以降の日付を入力してください');
      return;
    }

    filteredNotifications = allNotifications.filter(notification => {
      // カテゴリフィルター
      if (category && notification.通知種別 !== category) {
        return false;
      }

      // ステータスフィルター
      if (status === '未読' && notification.既読フラグ) {
        return false;
      }
      if (status === '既読' && !notification.既読フラグ) {
        return false;
      }

      // 日付範囲フィルター
      if (startDate || endDate) {
        const notificationDate = new Date(notification.送信日時);
        if (startDate && notificationDate < new Date(startDate)) {
          return false;
        }
        if (endDate && notificationDate > new Date(endDate + 'T23:59:59')) {
          return false;
        }
      }

      return true;
    });

    renderNotifications(filteredNotifications);
  }

  // 初期データ読み込み
  async function loadNotifications() {
    try {
      const notifications = await window.aivicApi.list(24); // 通知履歴テーブル
      if (notifications) {
        allNotifications = notifications.sort((a, b) => new Date(b.送信日時) - new Date(a.送信日時));
        filteredNotifications = [...allNotifications];
        renderNotifications(filteredNotifications);
      } else {
        showError('通知データの取得に失敗しました');
      }
    } catch (error) {
      showError('通知データの取得中にエラーが発生しました');
    }
  }

  // 通知を既読にする
  async function markAsRead(notificationId) {
    try {
      const updated = await window.aivicApi.update(24, notificationId, {
        既読フラグ: true,
        既読日時: new Date().toISOString()
      });
      if (updated) {
        // ローカルデータも更新
        const notification = allNotifications.find(n => n.通知履歴ID === notificationId);
        if (notification) {
          notification.既読フラグ = true;
          notification.既読日時 = new Date().toISOString();
        }
        applyFilters();
      } else {
        showError('既読更新に失敗しました');
      }
    } catch (error) {
      showError('既読更新中にエラーが発生しました');
    }
  }

  // 全て既読にする
  async function markAllAsRead() {
    const unreadNotifications = allNotifications.filter(n => !n.既読フラグ);
    if (unreadNotifications.length === 0) {
      return;
    }

    if (!confirm(`${unreadNotifications.length}件の未読通知を全て既読にしますか？`)) {
      return;
    }

    try {
      for (const notification of unreadNotifications) {
        await window.aivicApi.update(24, notification.通知履歴ID, {
          既読フラグ: true,
          既読日時: new Date().toISOString()
        });
        notification.既読フラグ = true;
        notification.既読日時 = new Date().toISOString();
      }
      applyFilters();
    } catch (error) {
      showError('一括既読処理中にエラーが発生しました');
    }
  }

  // 通知削除
  async function deleteNotification(notificationId) {
    if (!confirm('この通知を削除しますか？')) {
      return;
    }

    try {
      await window.aivicApi.delete(24, notificationId);
      allNotifications = allNotifications.filter(n => n.通知履歴ID !== notificationId);
      applyFilters();
    } catch (error) {
      showError('通知の削除に失敗しました');
    }
  }

  // プッシュ通知設定の保存
  async function savePushNotificationSetting(enabled) {
    try {
      // 通知設定マスタに保存（仮想的な処理）
      const settings = await window.aivicApi.list(23) || []; // 通知設定マスタ
      const pushSetting = settings.find(s => s.通知種別コード === 'PUSH_NOTIFICATION');

      if (pushSetting) {
        await window.aivicApi.update(23, pushSetting.通知設定ID, {
          通知有効フラグ: enabled
        });
      } else {
        await window.aivicApi.save(23, {
          受験生ID: 'current-student-id', // 実際の実装では現在の受験生IDを使用
          保護者ID: 'current-parent-id', // 実際の実装では現在の保護者IDを使用
          通知種別コード: 'PUSH_NOTIFICATION',
          通知種別名: 'プッシュ通知',
          通知方法: 'プッシュ通知',
          通知有効フラグ: enabled,
          通知タイミング: '即座',
          優先度: 2
        });
      }
    } catch (error) {
      showError('プッシュ通知設定の保存に失敗しました');
      // 設定を元に戻す
      container.querySelector('#push-notification-toggle').checked = !enabled;
    }
  }

  // イベントリスナー設定
  container.querySelector('#btn-apply-filter').addEventListener('click', applyFilters);

  container.querySelector('#btn-clear-filter').addEventListener('click', () => {
    container.querySelector('#filter-category').value = '';
    container.querySelector('#filter-status').value = '';
    container.querySelector('#filter-start-date').value = '';
    container.querySelector('#filter-end-date').value = '';
    filteredNotifications = [...allNotifications];
    renderNotifications(filteredNotifications);
  });

  container.querySelector('#btn-mark-all-read').addEventListener('click', markAllAsRead);

  container.querySelector('#btn-notification-settings').addEventListener('click', () => {
    window.showScreen('scr-1778233647948'); // 通知管理画面
  });

  container.querySelector('#push-notification-toggle').addEventListener('change', (e) => {
    savePushNotificationSetting(e.target.checked);
  });

  // 通知アイテムのクリックイベント（イベントデリゲーション）
  container.addEventListener('click', async (e) => {
    const notificationItem = e.target.closest('.notification-item');
    const deleteBtn = e.target.closest('.notification-delete');
    const gradeLink = e.target.closest('[data-action="grade-detail"]');
    const examLink = e.target.closest('[data-action="exam-result"]');

    if (deleteBtn) {
      e.stopPropagation();
      await deleteNotification(deleteBtn.dataset.id);
      return;
    }

    if (gradeLink) {
      e.preventDefault();
      e.stopPropagation();
      const dataId = gradeLink.dataset.id;
      if (dataId && dataId !== 'undefined') {
        window.showScreen('scr-1778235541740'); // 成績詳細表示画面
      } else {
        showError('関連する成績データが見つかりません');
      }
      return;
    }

    if (examLink) {
      e.preventDefault();
      e.stopPropagation();
      const dataId = examLink.dataset.id;
      if (dataId && dataId !== 'undefined') {
        window.showScreen('scr-1778233409974'); // 模試結果管理画面
      } else {
        showError('関連する模試結果データが見つかりません');
      }
      return;
    }

    if (notificationItem) {
      const notificationId = notificationItem.dataset.id;
      const notification = allNotifications.find(n => n.通知履歴ID === notificationId);

      if (notification && !notification.既読フラグ) {
        await markAsRead(notificationId);
      }

      // 通知詳細の展開/折りたたみ
      const isExpanded = notificationItem.classList.contains('notification-expanded');

      // 他の展開された通知を折りたたむ
      container.querySelectorAll('.notification-expanded').forEach(item => {
        item.classList.remove('notification-expanded');
        const details = item.querySelector('.notification-details');
        if (details) details.remove();
      });

      if (!isExpanded) {
        notificationItem.classList.add('notification-expanded');

        // 詳細情報を追加
        const detailsDiv = document.createElement('div');
        detailsDiv.className = 'notification-details';
        detailsDiv.innerHTML = `
          <div><strong>送信日時:</strong> ${formatDate(notification.送信日時)}</div>
          <div><strong>通知方法:</strong> ${notification.通知方法 || 'アプリ内通知'}</div>
          <div><strong>優先度:</strong> ${notification.優先度 || '中'}</div>
          ${notification.関連データ種別 ? `<div><strong>関連データ:</strong> ${notification.関連データ種別}</div>` : ''}
        `;
        notificationItem.appendChild(detailsDiv);
      }
    }
  });

  // 初期データ読み込み
  loadNotifications();

  // 初期表示時のプッシュ通知設定読み込み
  window.aivicApi.list(23).then(settings => {
    if (settings) {
      const pushSetting = settings.find(s => s.通知種別コード === 'PUSH_NOTIFICATION');
      if (pushSetting) {
        container.querySelector('#push-notification-toggle').checked = pushSetting.通知有効フラグ;
      }
    }
  }).catch(() => {
    // エラーは無視（設定が存在しない場合）
  });
}

function(container, apiUrl, tables) {
  let currentSettings = {};
  let schoolList = [];

  // スライダー値の更新
  function updateSliderValues() {
    const sliders = container.querySelectorAll('.importance-slider');
    sliders.forEach(slider => {
      const valueSpan = container.querySelector(`#${slider.id.replace('-slider', '-value')}`);
      if (valueSpan) {
        valueSpan.textContent = slider.value;
      }
    });
  }

  // 志望校リストの描画
  function renderSchoolList() {
    const schoolOrderList = container.querySelector('#school-order-list');
    const firstChoiceDisplay = container.querySelector('#first-choice-display');

    if (schoolList.length === 0) {
      schoolOrderList.innerHTML = '<p class="muted">志望校が登録されていません。</p>';
      firstChoiceDisplay.textContent = '未設定';
      return;
    }

    // 第一志望校の表示
    firstChoiceDisplay.textContent = schoolList[0]?.学校名 || '未設定';

    // 志望校リストの表示
    schoolOrderList.innerHTML = schoolList.map((school, index) => `
      <div class="school-item" data-index="${index}">
        <span>${index + 1}. ${school.学校名} ${school.学部名 ? `(${school.学部名})` : ''}</span>
        <div class="school-controls">
          <button class="move-btn move-up" data-index="${index}" ${index === 0 ? 'disabled' : ''}>↑</button>
          <button class="move-btn move-down" data-index="${index}" ${index === schoolList.length - 1 ? 'disabled' : ''}>↓</button>
        </div>
      </div>
    `).join('');
  }

  // エラーメッセージ表示
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => errorDiv.classList.add('hidden'), 5000);
  }

  // 成功メッセージ表示
  function showSuccess(message) {
    const successDiv = container.querySelector('#success-message');
    successDiv.textContent = message;
    successDiv.classList.remove('hidden');
    setTimeout(() => successDiv.classList.add('hidden'), 3000);
  }

  // バリデーション
  function validateSettings() {
    const selectedSubjects = Array.from(container.querySelectorAll('.subject-checkbox:checked'));
    if (selectedSubjects.length === 0) {
      showError('科目を選択してください');
      return false;
    }

    const examType = container.querySelector('#exam-type-select').value;
    const examImportance = container.querySelector('#exam-importance').value;
    if (examType && !examImportance) {
      showError('模試種別を選択した場合は重要度レベルも選択してください');
      return false;
    }

    const startDate = container.querySelector('#period-start').value;
    const endDate = container.querySelector('#period-end').value;
    if (startDate && endDate) {
      const start = new Date(startDate);
      const end = new Date(endDate);
      const today = new Date();
      today.setHours(0, 0, 0, 0);

      if (start < today) {
        showError('開始日は本日以降の日付を選択してください');
        return false;
      }

      if (end <= start) {
        showError('終了日は開始日より後の日付を指定してください');
        return false;
      }
    }

    return true;
  }

  // 設定データの収集
  function collectSettings() {
    const selectedSubjects = Array.from(container.querySelectorAll('.subject-checkbox:checked'))
      .map(cb => cb.value);

    const subjectImportance = {};
    selectedSubjects.forEach(subject => {
      const slider = container.querySelector(`#${subject === '国語' ? 'japanese' : 
        subject === '数学' ? 'math' : 
        subject === '英語' ? 'english' : 
        subject === '理科' ? 'science' : 'social'}-slider`);
      if (slider) {
        subjectImportance[subject] = parseInt(slider.value);
      }
    });

    return {
      selectedSubjects,
      subjectImportance,
      examType: container.querySelector('#exam-type-select').value,
      examImportance: container.querySelector('#exam-importance').value,
      periodStart: container.querySelector('#period-start').value,
      periodEnd: container.querySelector('#period-end').value,
      notificationPriority: container.querySelector('#notification-priority').value,
      notificationFrequency: container.querySelector('#notification-frequency').value,
      schoolOrder: schoolList.map(school => school.志望校登録ID)
    };
  }

  // 初期データの読み込み
  async function loadInitialData() {
    try {
      // 志望校データの読み込み
      const schoolData = await window.aivicApi.list(6); // 志望校登録データ
      if (schoolData) {
        schoolList = schoolData.sort((a, b) => a.志望順位 - b.志望順位);
        renderSchoolList();
      }

      // 既存の設定があれば読み込み（通知設定マスタから）
      const notificationSettings = await window.aivicApi.list(15); // 通知設定マスタ
      if (notificationSettings && notificationSettings.length > 0) {
        const setting = notificationSettings[0];
        container.querySelector('#notification-priority').value = setting.通知優先度 || '中';
        container.querySelector('#notification-frequency').value = setting.通知タイミング || '日次';
      }
    } catch (error) {
      console.error('初期データの読み込みに失敗しました:', error);
    }
  }

  // イベントリスナーの設定
  function setupEventListeners() {
    // スライダーの値変更
    container.querySelectorAll('.importance-slider').forEach(slider => {
      slider.addEventListener('input', updateSliderValues);
    });

    // 志望校順位調整
    container.addEventListener('click', (e) => {
      const moveBtn = e.target.closest('.move-btn');
      if (!moveBtn) return;

      const index = parseInt(moveBtn.dataset.index);
      if (moveBtn.classList.contains('move-up') && index > 0) {
        [schoolList[index], schoolList[index - 1]] = [schoolList[index - 1], schoolList[index]];
        renderSchoolList();
      } else if (moveBtn.classList.contains('move-down') && index < schoolList.length - 1) {
        [schoolList[index], schoolList[index + 1]] = [schoolList[index + 1], schoolList[index]];
        renderSchoolList();
      }
    });

    // 一括保存
    container.querySelector('#btn-save-all').addEventListener('click', async () => {
      if (!validateSettings()) return;

      try {
        const settings = collectSettings();

        // 通知設定の保存
        const notificationData = {
          通知種別コード: 'priority_settings',
          通知種別名: '優先度設定',
          通知方法: 'アプリ内通知',
          通知有効フラグ: settings.notificationPriority !== '無効',
          通知タイミング: settings.notificationFrequency,
          通知優先度: settings.notificationPriority === '高' ? 1 : settings.notificationPriority === '中' ? 2 : 3,
          作成日時: new Date().toISOString(),
          更新日時: new Date().toISOString()
        };

        const saved = await window.aivicApi.save(15, notificationData);
        if (saved) {
          // 志望校順位の更新
          for (let i = 0; i < schoolList.length; i++) {
            const school = schoolList[i];
            await window.aivicApi.update(6, school.志望校登録ID, {
              志望順位: i + 1,
              更新日時: new Date().toISOString()
            });
          }

          showSuccess('優先度設定が正常に保存されました');
        } else {
          showError('設定の保存に失敗しました');
        }
      } catch (error) {
        console.error('保存エラー:', error);
        showError('設定の保存中にエラーが発生しました');
      }
    });
  }

  // 初期化
  updateSliderValues();
  loadInitialData();
  setupEventListeners();

  // 今日の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#period-start').value = today;

  // 3ヶ月後を終了日に設定
  const threeMonthsLater = new Date();
  threeMonthsLater.setMonth(threeMonthsLater.getMonth() + 3);
  container.querySelector('#period-end').value = threeMonthsLater.toISOString().split('T')[0];
}

function(container, apiUrl, tables) {
  let currentStudentData = null;
  let currentSchoolData = [];
  let currentGradeData = [];

  // 初期化
  async function init() {
    await loadStudents();
    setDefaultDate();
    await loadNextExamInfo();
  }

  // 受験生一覧を読み込み
  async function loadStudents() {
    try {
      // 受験生データを取得（実際のテーブル構造に合わせて調整）
      const students = await window.aivicApi.list(0) || [];
      const selectStudent = container.querySelector("#select-student");

      selectStudent.innerHTML = '<option value="">受験生を選択してください</option>';
      students.forEach(student => {
        const option = document.createElement("option");
        option.value = student.id;
        option.textContent = student.受験生名 || student.name || `受験生${student.id}`;
        selectStudent.appendChild(option);
      });
    } catch (error) {
      console.error("受験生データの読み込みに失敗:", error);
    }
  }

  // デフォルト日付を設定
  function setDefaultDate() {
    const today = new Date();
    const dateStr = today.toISOString().split('T')[0];
    container.querySelector("#input-base-date").value = dateStr;
  }

  // 次回模試情報を読み込み
  async function loadNextExamInfo() {
    try {
      const examSchedules = await window.aivicApi.list(5) || []; // 模試日程データ
      const today = new Date();

      // 今日以降の模試を検索
      const upcomingExams = examSchedules.filter(exam => {
        const examDate = new Date(exam.実施日 || exam.exam_date);
        return examDate >= today;
      }).sort((a, b) => {
        const dateA = new Date(a.実施日 || a.exam_date);
        const dateB = new Date(b.実施日 || b.exam_date);
        return dateA - dateB;
      });

      if (upcomingExams.length > 0) {
        const nextExam = upcomingExams[0];
        const examDate = new Date(nextExam.実施日 || nextExam.exam_date);
        const diffTime = examDate - today;
        const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

        container.querySelector("#days-to-exam").textContent = `${diffDays}日`;
        container.querySelector("#next-exam-name").textContent = nextExam.模試名 || nextExam.exam_name || "模試";
      } else {
        container.querySelector("#days-to-exam").textContent = "--日";
        container.querySelector("#next-exam-name").textContent = "予定なし";
      }
    } catch (error) {
      console.error("模試情報の読み込みに失敗:", error);
    }
  }

  // エラー表示
  function showError(message) {
    const errorDiv = container.querySelector("#error-message");
    const errorText = container.querySelector("#error-text");
    errorText.textContent = message;
    errorDiv.classList.remove("hidden");

    setTimeout(() => {
      errorDiv.classList.add("hidden");
    }, 5000);
  }

  // ローディング表示制御
  function showLoading(show) {
    const loading = container.querySelector("#loading");
    if (show) {
      loading.classList.remove("hidden");
    } else {
      loading.classList.add("hidden");
    }
  }

  // 優先度判定実行
  async function executePriorityJudgment() {
    const studentId = container.querySelector("#select-student").value;
    const baseDate = container.querySelector("#input-base-date").value;

    // バリデーション
    if (!studentId) {
      showError("受験生を選択してください。");
      return;
    }

    if (!baseDate) {
      showError("判定基準日付を入力してください。");
      return;
    }

    // 日付の妥当性チェック
    const baseDateObj = new Date(baseDate);
    if (isNaN(baseDateObj.getTime())) {
      showError("日付の形式が正しくありません。");
      return;
    }

    showLoading(true);

    try {
      // 各種データを並行取得
      const [schoolData, gradeData, deviationData] = await Promise.all([
        window.aivicApi.list(6), // 志望校登録データ
        window.aivicApi.list(3), // 科目別成績データ
        window.aivicApi.list(4)  // 偏差値履歴データ
      ]);

      // 選択された受験生のデータをフィルタリング
      const studentSchools = (schoolData || []).filter(s => s.受験生ID === studentId);
      const studentGrades = (gradeData || []).filter(g => g.受験生ID === studentId);
      const studentDeviations = (deviationData || []).filter(d => d.受験生ID === studentId);

      // データ存在チェック
      if (studentSchools.length === 0) {
        showError("志望校が登録されていません。先に志望校を登録してください。");
        showLoading(false);
        return;
      }

      if (studentGrades.length === 0) {
        showError("成績データが登録されていません。先に成績データを登録してください。");
        showLoading(false);
        return;
      }

      // 判定処理実行
      await performJudgment(studentSchools, studentGrades, studentDeviations, baseDateObj);

      // 結果表示
      container.querySelector("#result-area").classList.remove("hidden");

    } catch (error) {
      console.error("優先度判定処理エラー:", error);
      showError("優先度判定処理中にエラーが発生しました。ネットワーク環境をご確認の上、再度お試しください。");
    } finally {
      showLoading(false);
    }
  }

  // 判定処理実行
  async function performJudgment(schools, grades, deviations, baseDate) {
    // 志望校一覧表示
    displaySchools(schools);

    // 現在偏差値・目標偏差値計算
    const { currentDev, targetDev } = calculateDeviations(grades, schools);
    container.querySelector("#current-deviation").textContent = currentDev;
    container.querySelector("#target-deviation").textContent = targetDev;

    // 科目別優先度ランキング計算
    const priorityRanking = calculatePriorityRanking(grades, schools);
    displayPriorityRanking(priorityRanking);

    // 合格可能性計算
    const passProbability = calculatePassProbability(currentDev, schools);
    displayPassProbability(passProbability);

    // 推奨学習時間配分グラフ描画
    drawStudyTimeChart(priorityRanking);

    // 緊急度レベル表示
    displayUrgencyLevel(priorityRanking, passProbability);

    // 判定結果詳細表示
    displayResultDetails(priorityRanking, passProbability, currentDev, targetDev);
  }

  // 志望校一覧表示
  function displaySchools(schools) {
    const tbody = container.querySelector("#school-tbody");
    tbody.innerHTML = schools.map((school, index) => `
      <tr>
        <td>${school.志望順位 || (index + 1)}</td>
        <td>${school.学校名 || "--"}</td>
        <td>${school.学部名 || "--"}${school.学科名 ? ` ${school.学科名}` : ""}</td>
        <td>${school.必要偏差値 || "--"}</td>
        <td id="prob-${school.id}">計算中...</td>
      </tr>
    `).join("");
  }

  // 偏差値計算
  function calculateDeviations(grades, schools) {
    if (grades.length === 0) return { currentDev: "--", targetDev: "--" };

    // 最新の総合偏差値を計算（簡易版）
    const latestGrades = grades.sort((a, b) => new Date(b.実施日) - new Date(a.実施日));
    const avgDeviation = latestGrades.slice(0, 5).reduce((sum, g) => sum + (g.偏差値 || 50), 0) / Math.min(5, latestGrades.length);

    // 第一志望校の必要偏差値を目標とする
    const firstChoice = schools.find(s => s.志望順位 === 1) || schools[0];
    const targetDeviation = firstChoice?.必要偏差値 || avgDeviation + 10;

    return {
      currentDev: Math.round(avgDeviation),
      targetDev: targetDeviation
    };
  }

  // 科目別優先度ランキング計算
  function calculatePriorityRanking(grades, schools) {
    const subjectMap = new Map();

    // 科目別の最新偏差値を集計
    grades.forEach(grade => {
      const subject = grade.科目名 || grade.科目コード;
      if (!subject) return;

      if (!subjectMap.has(subject)) {
        subjectMap.set(subject, {
          subject: subject,
          currentDeviation: grade.偏差値 || 50,
          targetDeviation: grade.目標偏差値 || 60,
          lastUpdate: new Date(grade.実施日 || Date.now())
        });
      } else {
        const existing = subjectMap.get(subject);
        const gradeDate = new Date(grade.実施日 || Date.now());
        if (gradeDate > existing.lastUpdate) {
          existing.currentDeviation = grade.偏差値 || existing.currentDeviation;
          existing.targetDeviation = grade.目標偏差値 || existing.targetDeviation;
          existing.lastUpdate = gradeDate;
        }
      }
    });

    // 優先度計算（目標との差が大きいほど高優先度）
    const ranking = Array.from(subjectMap.values()).map(item => {
      const gap = item.targetDeviation - item.currentDeviation;
      const priority = gap > 15 ? "最高" : gap > 10 ? "高" : gap > 5 ? "中" : "低";
      const urgency = gap > 20 ? 4 : gap > 15 ? 3 : gap > 10 ? 2 : 1;

      return {
        ...item,
        gap: gap,
        priority: priority,
        urgency: urgency,
        urgencyText: urgency === 4 ? "緊急" : urgency === 3 ? "高" : urgency === 2 ? "中" : "低"
      };
    });

    // 優先度順にソート
    ranking.sort((a, b) => b.gap - a.gap);

    return ranking;
  }

  // 優先度ランキング表示
  function displayPriorityRanking(ranking) {
    const tbody = container.querySelector("#priority-tbody");
    tbody.innerHTML = ranking.map((item, index) => {
      const priorityColor = item.urgency === 4 ? "#dc3545" : 
                           item.urgency === 3 ? "#fd7e14" : 
                           item.urgency === 2 ? "#ffc107" : "#28a745";

      return `
        <tr>
          <td>${index + 1}</td>
          <td>${item.subject}</td>
          <td>${item.currentDeviation}</td>
          <td>${item.targetDeviation}</td>
          <td style="color: ${priorityColor}; font-weight: bold;">${item.priority}</td>
          <td style="color: ${priorityColor}; font-weight: bold;">${item.urgencyText}</td>
        </tr>
      `;
    }).join("");
  }

  // 合格可能性計算
  function calculatePassProbability(currentDev, schools) {
    const firstChoice = schools.find(s => s.志望順位 === 1) || schools[0];
    if (!firstChoice || !firstChoice.必要偏差値) return { probability: 0, judgment: "E判定" };

    const requiredDev = firstChoice.必要偏差値;
    const diff = currentDev - requiredDev;

    let probability, judgment;
    if (diff >= 10) {
      probability = 85;
      judgment = "A判定";
    } else if (diff >= 5) {
      probability = 70;
      judgment = "B判定";
    } else if (diff >= 0) {
      probability = 55;
      judgment = "C判定";
    } else if (diff >= -5) {
      probability = 35;
      judgment = "D判定";
    } else {
      probability = 15;
      judgment = "E判定";
    }

    return { probability, judgment };
  }

  // 合格可能性表示
  function displayPassProbability(passProbability) {
    container.querySelector("#pass-probability").textContent = `${passProbability.probability}%`;
    container.querySelector("#pass-judgment").textContent = passProbability.judgment;

    const probColor = passProbability.probability >= 70 ? "#28a745" :
                     passProbability.probability >= 50 ? "#ffc107" : "#dc3545";

    container.querySelector("#pass-probability").style.color = probColor;
    container.querySelector("#pass-judgment").style.color = probColor;
  }

  // 学習時間配分グラフ描画
  function drawStudyTimeChart(ranking) {
    const canvas = container.querySelector("#study-time-chart");
    const ctx = canvas.getContext("2d");

    // キャンバスクリア
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (ranking.length === 0) {
      ctx.fillStyle = "#9fb0d1";
      ctx.font = "16px Arial";
      ctx.textAlign = "center";
      ctx.fillText("データがありません", canvas.width / 2, canvas.height / 2);
      return;
    }

    // 推奨学習時間計算（優先度に基づく）
    const totalTime = 100; // 週100時間として配分
    const weights = ranking.map(item => item.urgency);
    const totalWeight = weights.reduce((sum, w) => sum + w, 0);

    const studyTimes = ranking.map((item, index) => ({
      subject: item.subject,
      time: Math.round((item.urgency / totalWeight) * totalTime),
      color: `hsl(${index * 360 / ranking.length}, 70%, 50%)`
    }));

    // 棒グラフ描画
    const margin = 60;
    const chartWidth = canvas.width - margin * 2;
    const chartHeight = canvas.height - margin * 2;
    const barWidth = chartWidth / studyTimes.length * 0.8;
    const maxTime = Math.max(...studyTimes.map(s => s.time));

    studyTimes.forEach((item, index) => {
      const x = margin + (chartWidth / studyTimes.length) * index + (chartWidth / studyTimes.length - barWidth) / 2;
      const barHeight = (item.time / maxTime) * chartHeight;
      const y = margin + chartHeight - barHeight;

      // 棒描画
      ctx.fillStyle = item.color;
      ctx.fillRect(x, y, barWidth, barHeight);

      // 科目名
      ctx.fillStyle = "#1a2a40";
      ctx.font = "12px Arial";
      ctx.textAlign = "center";
      ctx.save();
      ctx.translate(x + barWidth / 2, margin + chartHeight + 20);
      ctx.rotate(-Math.PI / 4);
      ctx.fillText(item.subject, 0, 0);
      ctx.restore();

      // 時間表示
      ctx.fillStyle = "#1a2a40";
      ctx.font = "10px Arial";
      ctx.textAlign = "center";
      ctx.fillText(`${item.time}h`, x + barWidth / 2, y - 5);
    });

    // Y軸ラベル
    ctx.fillStyle = "#1a2a40";
    ctx.font = "12px Arial";
    ctx.textAlign = "right";
    for (let i = 0; i <= 5; i++) {
      const value = Math.round((maxTime / 5) * i);
      const y = margin + chartHeight - (chartHeight / 5) * i;
      ctx.fillText(`${value}h`, margin - 10, y + 4);
    }

    // タイトル
    ctx.fillStyle = "#1a2a40";
    ctx.font = "16px Arial";
    ctx.textAlign = "center";
    ctx.fillText("週間推奨学習時間配分", canvas.width / 2, 30);
  }

  // 緊急度レベル表示
  function displayUrgencyLevel(ranking, passProbability) {
    if (ranking.length === 0) return;

    const maxUrgency = Math.max(...ranking.map(r => r.urgency));
    const urgencyText = maxUrgency === 4 ? "緊急" : maxUrgency === 3 ? "高" : maxUrgency === 2 ? "中" : "低";
    const urgencyColor = maxUrgency === 4 ? "#dc3545" : 
                        maxUrgency === 3 ? "#fd7e14" : 
                        maxUrgency === 2 ? "#ffc107" : "#28a745";

    const urgencyLevel = container.querySelector("#urgency-level");
    urgencyLevel.style.backgroundColor = `${urgencyColor}20`;
    urgencyLevel.style.borderLeft = `4px solid ${urgencyColor}`;
    urgencyLevel.querySelector("div").style.color = urgencyColor;
    urgencyLevel.querySelector("div").textContent = `緊急度: ${urgencyText}`;

    // 詳細情報
    const details = container.querySelector("#urgency-details");
    const urgentSubjects = ranking.filter(r => r.urgency >= 3);

    if (urgentSubjects.length > 0) {
      details.innerHTML = `
        <div style="color: var(--text); margin-bottom: 10px;"><strong>要注意科目:</strong></div>
        ${urgentSubjects.map(s => `
          <div style="padding: 8px; background: var(--bg-card); border-radius: 4px; margin-bottom: 5px; color: var(--text);">
            ${s.subject}: 目標まで${s.gap}ポイント不足
          </div>
        `).join("")}
      `;
    } else {
      details.innerHTML = `<div style="color: var(--text);">現在のペースを維持してください。</div>`;
    }
  }

  // 判定結果詳細表示
  function displayResultDetails(ranking, passProbability, currentDev, targetDev) {
    const overallAssessment = container.querySelector("#overall-assessment");
    const recommendedActions = container.querySelector("#recommended-actions");

    // 総合評価
    const devGap = targetDev - currentDev;
    let assessment;
    if (devGap <= 0) {
      assessment = "目標偏差値を達成しています。現在の学習を継続し、安定した成績維持を心がけてください。";
    } else if (devGap <= 5) {
      assessment = "目標まであと少しです。苦手分野の克服に集中することで合格可能性を高められます。";
    } else if (devGap <= 10) {
      assessment = "計画的な学習により目標達成は十分可能です。優先度の高い科目から重点的に取り組みましょう。";
    } else {
      assessment = "目標達成には相当な努力が必要です。学習計画の見直しと集中的な対策が必要です。";
    }

    overallAssessment.textContent = assessment;

    // 推奨アクション
    const urgentSubjects = ranking.filter(r => r.urgency >= 3);
    let actions = [];

    if (urgentSubjects.length > 0) {
      actions.push(`最優先: ${urgentSubjects[0].subject}の基礎固めと弱点克服`);
      if (urgentSubjects.length > 1) {
        actions.push(`次優先: ${urgentSubjects[1].subject}の集中学習`);
      }
    }

    if (passProbability.probability < 50) {
      actions.push("志望校の見直しまたは併願校の検討");
    }

    actions.push("定期的な模試受験による進捗確認");
    actions.push("学習時間の確保と効率的な勉強法の実践");

    recommendedActions.innerHTML = actions.map(action => 
      `<div style="padding: 8px 0; border-bottom: 1px solid var(--border); color: var(--text);">• ${action}</div>`
    ).join("");
  }

  // イベントリスナー設定
  container.querySelector("#btn-execute").addEventListener("click", executePriorityJudgment);

  // 初期化実行
  init();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#tbody-schools");
  let allSchools = [];
  let selectedSchoolIds = new Set();

  // 1. 再描画関数の定義
  function renderRows(rows) {
    allSchools = rows || [];
    tbody.innerHTML = allSchools.map(r => {
      const priorityText = r.志望順位 ? `第${r.志望順位}志望` : '-';
      const deviationDiff = r.偏差値差分 ? (r.偏差値差分 > 0 ? `+${r.偏差値差分}` : r.偏差値差分) : '-';
      const possibilityColor = r.合格可能性判定 === 'A判定' ? '#2ecc71' : 
                              r.合格可能性判定 === 'B判定' ? '#3498db' :
                              r.合格可能性判定 === 'C判定' ? '#f39c12' :
                              r.合格可能性判定 === 'D判定' ? '#e67e22' :
                              r.合格可能性判定 === 'E判定' ? '#e74c3c' : 'var(--text)';

      return `<tr data-id="${r.id}">
        <td><input type="checkbox" class="row-check" data-id="${r.id}" ${selectedSchoolIds.has(r.id) ? 'checked' : ''}></td>
        <td>${priorityText}</td>
        <td>${r.学校名 || ""}</td>
        <td>${r.学部名 || ""}</td>
        <td>${r.学科名 || ""}</td>
        <td>${r.入試方式 || ""}</td>
        <td>${r.必要偏差値 || "-"}</td>
        <td style="color: ${r.偏差値差分 < 0 ? '#e74c3c' : '#2ecc71'};">${deviationDiff}</td>
        <td style="color: ${possibilityColor};">${r.合格可能性判定 || "-"}</td>
        <td>${r.入試日程 ? new Date(r.入試日程).toLocaleDateString('ja-JP') : ""}</td>
        <td>
          <button class="action-btn secondary edit-btn" data-id="${r.id}">編集</button>
          <button class="action-btn secondary delete-btn" data-id="${r.id}">削除</button>
        </td>
      </tr>`;
    }).join("");

    updateDeleteButtonState();
  }

  // 2. 初期データ読み込み
  window.aivicApi.list(0).then(rows => {
    renderRows(rows);
  });

  // 3. 検索機能
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const schoolName = container.querySelector("#input-school-search").value.trim();
    const schoolType = container.querySelector("#select-school-type").value;
    const prefecture = container.querySelector("#select-prefecture").value;

    const rows = await window.aivicApi.list(0);
    const filtered = rows.filter(r => {
      const matchName = !schoolName || (r.学校名 && r.学校名.includes(schoolName));
      const matchType = !schoolType || r.国公私立区分 === schoolType;
      const matchPrefecture = !prefecture || r.所在地都道府県 === prefecture;
      return matchName && matchType && matchPrefecture;
    });

    renderRows(filtered);
  });

  // 4. 志望校登録機能
  container.querySelector("#btn-save").addEventListener("click", async () => {
    const schoolName = container.querySelector("#input-school-name").value.trim();
    const department = container.querySelector("#input-department").value.trim();
    const major = container.querySelector("#input-major").value.trim();
    const examType = container.querySelector("#select-exam-type").value;
    const priority = container.querySelector("#select-priority").value;
    const examDate = container.querySelector("#input-exam-date").value;

    // バリデーション
    if (!schoolName) {
      alert("学校名を入力してください。");
      return;
    }

    if (schoolName.length > 255) {
      alert("学校名は255文字以内で入力してください。");
      return;
    }

    if (!examType) {
      alert("入試方式を選択してください。");
      return;
    }

    if (!priority) {
      alert("志望順位を選択してください。");
      return;
    }

    // 志望順位重複チェック
    const existingRows = await window.aivicApi.list(0);
    const duplicatePriority = existingRows.find(r => r.志望順位 === parseInt(priority));
    if (duplicatePriority) {
      alert("同じ志望順位が既に登録されています。別の志望順位を選択してください。");
      return;
    }

    // 登録上限チェック（第10志望まで）
    if (existingRows.length >= 10) {
      alert("志望校は最大10校まで登録可能です。");
      return;
    }

    // 複数入試方式の取得
    const examTypeChecks = container.querySelectorAll(".exam-type-check:checked");
    const selectedExamTypes = Array.from(examTypeChecks).map(cb => cb.value);
    const finalExamType = selectedExamTypes.length > 0 ? selectedExamTypes.join(", ") : examType;

    const newSchool = {
      学校名: schoolName,
      学部名: department,
      学科名: major,
      入試方式: finalExamType,
      志望順位: parseInt(priority),
      入試日程: examDate || null,
      必要偏差値: Math.floor(Math.random() * 20) + 50, // サンプル偏差値
      偏差値差分: Math.floor(Math.random() * 21) - 10, // -10から+10のランダム
      合格可能性判定: ['A判定', 'B判定', 'C判定', 'D判定', 'E判定'][Math.floor(Math.random() * 5)],
      登録日時: new Date().toISOString(),
      削除フラグ: false
    };

    const saved = await window.aivicApi.save(0, newSchool);
    if (saved) {
      // フォームクリア
      container.querySelector("#input-school-name").value = "";
      container.querySelector("#input-department").value = "";
      container.querySelector("#input-major").value = "";
      container.querySelector("#select-exam-type").value = "";
      container.querySelector("#select-priority").value = "";
      container.querySelector("#input-exam-date").value = "";
      container.querySelectorAll(".exam-type-check").forEach(cb => cb.checked = false);
      container.querySelector("#check-all-exam-types").checked = false;

      // 一覧更新
      const updatedRows = await window.aivicApi.list(0);
      renderRows(updatedRows);

      alert("志望校が正常に登録されました。");
    }
  });

  // フォームクリア機能
  container.querySelector("#btn-clear").addEventListener("click", () => {
    container.querySelector("#input-school-name").value = "";
    container.querySelector("#input-department").value = "";
    container.querySelector("#input-major").value = "";
    container.querySelector("#select-exam-type").value = "";
    container.querySelector("#select-priority").value = "";
    container.querySelector("#input-exam-date").value = "";
    container.querySelectorAll(".exam-type-check").forEach(cb => cb.checked = false);
    container.querySelector("#check-all-exam-types").checked = false;
  });

  // 全入試方式選択機能
  container.querySelector("#check-all-exam-types").addEventListener("change", (e) => {
    const isChecked = e.target.checked;
    container.querySelectorAll(".exam-type-check").forEach(cb => {
      cb.checked = isChecked;
    });
  });

  // 合格可能性算出ボタン
  container.querySelector("#btn-calculate-possibility").addEventListener("click", () => {
    window.showScreen("scr-1778233861021");
  });

  // 5. 行レベル操作のイベントデリゲーション
  container.addEventListener("click", async (e) => {
    // 削除ボタン
    const deleteBtn = e.target.closest(".delete-btn");
    if (deleteBtn) {
      if (!confirm("この志望校を削除しますか？")) return;

      await window.aivicApi.delete(0, deleteBtn.dataset.id);
      const updatedRows = await window.aivicApi.list(0);
      renderRows(updatedRows);
      selectedSchoolIds.clear();
      return;
    }

    // 編集ボタン
    const editBtn = e.target.closest(".edit-btn");
    if (editBtn) {
      const schoolId = editBtn.dataset.id;
      const school = allSchools.find(s => s.id === schoolId);
      if (school) {
        container.querySelector("#input-school-name").value = school.学校名 || "";
        container.querySelector("#input-department").value = school.学部名 || "";
        container.querySelector("#input-major").value = school.学科名 || "";
        container.querySelector("#select-exam-type").value = school.入試方式 || "";
        container.querySelector("#select-priority").value = school.志望順位 || "";
        container.querySelector("#input-exam-date").value = school.入試日程 ? school.入試日程.split('T')[0] : "";

        // 編集モード表示
        const saveBtn = container.querySelector("#btn-save");
        saveBtn.textContent = "更新";
        saveBtn.dataset.editId = schoolId;
      }
      return;
    }

    // チェックボックス処理
    const rowCheck = e.target.closest(".row-check");
    if (rowCheck) {
      const schoolId = rowCheck.dataset.id;
      if (rowCheck.checked) {
        selectedSchoolIds.add(schoolId);
      } else {
        selectedSchoolIds.delete(schoolId);
      }
      updateDeleteButtonState();
      return;
    }
  });

  // 全選択チェックボックス
  container.querySelector("#check-all").addEventListener("change", (e) => {
    const isChecked = e.target.checked;
    container.querySelectorAll(".row-check").forEach(cb => {
      cb.checked = isChecked;
      const schoolId = cb.dataset.id;
      if (isChecked) {
        selectedSchoolIds.add(schoolId);
      } else {
        selectedSchoolIds.delete(schoolId);
      }
    });
    updateDeleteButtonState();
  });

  // 選択削除ボタン
  container.querySelector("#btn-delete-selected").addEventListener("click", async () => {
    if (selectedSchoolIds.size === 0) {
      alert("削除する志望校を選択してください。");
      return;
    }

    if (!confirm(`選択した${selectedSchoolIds.size}件の志望校を削除しますか？`)) return;

    for (const schoolId of selectedSchoolIds) {
      await window.aivicApi.delete(0, schoolId);
    }

    selectedSchoolIds.clear();
    const updatedRows = await window.aivicApi.list(0);
    renderRows(updatedRows);
  });

  // 削除ボタン状態更新
  function updateDeleteButtonState() {
    const deleteBtn = container.querySelector("#btn-delete-selected");
    deleteBtn.disabled = selectedSchoolIds.size === 0;
  }

  // CSVエクスポート機能
  container.querySelector("#btn-export-csv").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(0);
    const headers = ["志望順位", "学校名", "学部名", "学科名", "入試方式", "合格ライン偏差値", "偏差値差分", "合格可能性判定", "入試日程"];

    const csvContent = [
      "\uFEFF" + headers.join(","),
      ...rows.map(r => [
        r.志望順位 || "",
        `"${(r.学校名 || "").replace(/"/g, '""')}"`,
        `"${(r.学部名 || "").replace(/"/g, '""')}"`,
        `"${(r.学科名 || "").replace(/"/g, '""')}"`,
        `"${(r.入試方式 || "").replace(/"/g, '""')}"`,
        r.必要偏差値 || "",
        r.偏差値差分 || "",
        `"${(r.合格可能性判定 || "").replace(/"/g, '""')}"`,
        r.入試日程 ? new Date(r.入試日程).toLocaleDateString('ja-JP') : ""
      ].join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "志望校一覧.csv";
    link.click();
  });

  // 合格ライン偏差値表示更新
  function updateDeviationDisplay() {
    const schoolName = container.querySelector("#input-school-name").value.trim();
    if (schoolName) {
      // サンプル表示
      const requiredDeviation = Math.floor(Math.random() * 20) + 50;
      const currentDeviation = Math.floor(Math.random() * 20) + 45;
      const diff = currentDeviation - requiredDeviation;

      container.querySelector("#display-required-deviation").textContent = requiredDeviation;
      container.querySelector("#display-deviation-diff").textContent = diff > 0 ? `+${diff}` : diff;
      container.querySelector("#display-deviation-diff").style.color = diff < 0 ? '#e74c3c' : '#2ecc71';

      const possibility = diff >= 10 ? 'A判定' : diff >= 5 ? 'B判定' : diff >= 0 ? 'C判定' : diff >= -5 ? 'D判定' : 'E判定';
      container.querySelector("#display-possibility-result").textContent = possibility;

      const possibilityColor = possibility === 'A判定' ? '#2ecc71' : 
                              possibility === 'B判定' ? '#3498db' :
                              possibility === 'C判定' ? '#f39c12' :
                              possibility === 'D判定' ? '#e67e22' : '#e74c3c';
      container.querySelector("#display-possibility-result").style.color = possibilityColor;
    } else {
      container.querySelector("#display-required-deviation").textContent = "-";
      container.querySelector("#display-deviation-diff").textContent = "-";
      container.querySelector("#display-possibility-result").textContent = "-";
    }
  }

  // 学校名入力時の偏差値表示更新
  container.querySelector("#input-school-name").addEventListener("input", updateDeviationDisplay);
}

function(container, apiUrl, tables) {
  let currentAnalysisData = null;
  let selectedSchools = [];

  // エラー表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    const errorText = container.querySelector('#error-text');
    errorText.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => {
      errorDiv.classList.add('hidden');
    }, 5000);
  }

  // ローディング表示制御
  function showLoading(show) {
    const overlay = container.querySelector('#loading-overlay');
    if (show) {
      overlay.classList.remove('hidden');
    } else {
      overlay.classList.add('hidden');
    }
  }

  // 受験生データを読み込み
  async function loadStudents() {
    try {
      const studentSelect = container.querySelector('#target-student');
      // 模擬データとして受験生を追加
      const students = [
        { id: '1', name: '田中太郎' },
        { id: '2', name: '佐藤花子' },
        { id: '3', name: '鈴木次郎' }
      ];

      students.forEach(student => {
        const option = document.createElement('option');
        option.value = student.id;
        option.textContent = student.name;
        studentSelect.appendChild(option);
      });
    } catch (error) {
      showError('受験生データの読み込みに失敗しました');
    }
  }

  // 志望校データを読み込み
  async function loadSchools() {
    try {
      const schoolSelection = container.querySelector('#school-selection');
      // 模擬データとして志望校を追加
      const schools = [
        { id: '1', name: '東京大学 理科一類', deviation: 72 },
        { id: '2', name: '早稲田大学 理工学部', deviation: 65 },
        { id: '3', name: '慶應義塾大学 理工学部', deviation: 67 },
        { id: '4', name: '東京工業大学 工学院', deviation: 68 },
        { id: '5', name: '明治大学 理工学部', deviation: 60 }
      ];

      schools.forEach(school => {
        const div = document.createElement('div');
        div.innerHTML = `
          <label style="display: flex; align-items: center; gap: 8px; cursor: pointer;">
            <input type="checkbox" value="${school.id}" class="school-checkbox">
            <span style="color: var(--text);">${school.name} (偏差値: ${school.deviation})</span>
          </label>
        `;
        schoolSelection.appendChild(div);
      });

      // チェックボックスのイベントリスナー
      schoolSelection.addEventListener('change', (e) => {
        if (e.target.classList.contains('school-checkbox')) {
          updateSelectedSchools();
          checkAnalysisReadiness();
        }
      });
    } catch (error) {
      showError('志望校データの読み込みに失敗しました');
    }
  }

  // 選択された志望校を更新
  function updateSelectedSchools() {
    const checkboxes = container.querySelectorAll('.school-checkbox:checked');
    selectedSchools = Array.from(checkboxes).map(cb => cb.value);
  }

  // 分析実行の準備状況をチェック
  function checkAnalysisReadiness() {
    const period = container.querySelector('#analysis-period').value;
    const student = container.querySelector('#target-student').value;
    const executeBtn = container.querySelector('#btn-execute-analysis');

    if (period && student && selectedSchools.length > 0) {
      executeBtn.disabled = false;
    } else {
      executeBtn.disabled = true;
    }
  }

  // 優先度分析を実行
  async function executeAnalysis() {
    const period = container.querySelector('#analysis-period').value;
    const student = container.querySelector('#target-student').value;

    if (!period) {
      showError('分析対象期間を選択してください');
      return;
    }

    if (!student) {
      showError('対象受験生を選択してください');
      return;
    }

    if (selectedSchools.length === 0) {
      showError('志望校を選択してください');
      return;
    }

    showLoading(true);

    try {
      // 模擬的な分析処理（実際はAPIを呼び出し）
      await new Promise(resolve => setTimeout(resolve, 2000));

      // 模擬分析結果データを生成
      currentAnalysisData = generateMockAnalysisData();

      // 結果を表示
      displayAnalysisResults();

      // 結果エリアを表示
      container.querySelector('#analysis-results').classList.remove('hidden');

    } catch (error) {
      showError('分析処理中にエラーが発生しました');
    } finally {
      showLoading(false);
    }
  }

  // 模擬分析データを生成
  function generateMockAnalysisData() {
    const subjects = ['数学', '英語', '国語', '物理', '化学'];
    const priorityData = subjects.map((subject, index) => ({
      rank: index + 1,
      subject: subject,
      priorityScore: Math.floor(Math.random() * 40) + 60,
      improvementLevel: ['高', '中', '低'][Math.floor(Math.random() * 3)],
      deviationDiff: Math.floor(Math.random() * 20) - 10,
      urgency: ['critical', 'high', 'normal'][Math.floor(Math.random() * 3)]
    }));

    const weaknessData = [
      { subject: '数学', field: '微分積分', scoreRate: 45, level: 'high', suggestion: '基礎問題の反復練習', studyTime: 120 },
      { subject: '英語', field: '長文読解', scoreRate: 60, level: 'medium', suggestion: '語彙力強化', studyTime: 90 },
      { subject: '物理', field: '力学', scoreRate: 55, level: 'medium', suggestion: '公式の理解を深める', studyTime: 100 },
      { subject: '化学', field: '有機化学', scoreRate: 40, level: 'high', suggestion: '反応機構の暗記', studyTime: 110 }
    ];

    return {
      priority: priorityData,
      weakness: weaknessData,
      achievement: selectedSchools.map(schoolId => ({
        schoolId: schoolId,
        schoolName: `志望校${schoolId}`,
        achievementRate: Math.floor(Math.random() * 40) + 60
      })),
      studyTime: {
        '数学': 30,
        '英語': 25,
        '国語': 15,
        '物理': 20,
        '化学': 10
      }
    };
  }

  // 分析結果を表示
  function displayAnalysisResults() {
    if (!currentAnalysisData) return;

    // 科目別優先度ランキングを表示
    displayPriorityRanking();

    // 合格ライン到達度を表示
    displayAchievementProgress();

    // 学習時間配分円グラフを表示
    displayStudyTimeChart();

    // 分野別弱点一覧を表示
    displayWeaknessAnalysis();
  }

  // 科目別優先度ランキング表示
  function displayPriorityRanking() {
    const tbody = container.querySelector('#priority-ranking-tbody');
    tbody.innerHTML = currentAnalysisData.priority.map(item => `
      <tr>
        <td>${item.rank}</td>
        <td style="color: var(--text); font-weight: bold;">${item.subject}</td>
        <td style="color: var(--text);">${item.priorityScore}</td>
        <td>
          <span class="priority-indicator priority-${item.improvementLevel === '高' ? 'high' : item.improvementLevel === '中' ? 'medium' : 'low'}">
            ${item.improvementLevel}
          </span>
        </td>
        <td style="color: var(--text); ${item.deviationDiff < 0 ? 'color: #dc3545;' : ''}">${item.deviationDiff > 0 ? '+' : ''}${item.deviationDiff}</td>
        <td>
          <span class="urgency-icon urgency-${item.urgency}" title="緊急度: ${item.urgency}">!</span>
        </td>
        <td>
          <button class="detail-expand-btn" data-subject="${item.subject}">詳細を見る</button>
        </td>
      </tr>
    `).join('');
  }

  // 合格ライン到達度表示
  function displayAchievementProgress() {
    const progressDiv = container.querySelector('#achievement-progress');
    progressDiv.innerHTML = currentAnalysisData.achievement.map(item => `
      <div style="margin-bottom: 15px;">
        <div style="color: var(--text); margin-bottom: 5px; font-weight: bold;">${item.schoolName}</div>
        <div class="progress-bar">
          <div class="progress-fill" style="width: ${item.achievementRate}%;">
            ${item.achievementRate}%
          </div>
        </div>
      </div>
    `).join('');
  }

  // 学習時間配分円グラフ表示
  function displayStudyTimeChart() {
    const canvas = container.querySelector('#study-time-chart');
    const ctx = canvas.getContext('2d');
    const data = currentAnalysisData.studyTime;

    const total = Object.values(data).reduce((sum, val) => sum + val, 0);
    const colors = ['#ff6b6b', '#4ecdc4', '#45b7d1', '#96ceb4', '#feca57'];

    // キャンバスをクリア
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const centerX = canvas.width / 2;
    const centerY = canvas.height / 2;
    const radius = 150;

    let currentAngle = 0;

    Object.entries(data).forEach(([subject, time], index) => {
      const sliceAngle = (time / total) * 2 * Math.PI;

      // スライスを描画
      ctx.beginPath();
      ctx.moveTo(centerX, centerY);
      ctx.arc(centerX, centerY, radius, currentAngle, currentAngle + sliceAngle);
      ctx.closePath();
      ctx.fillStyle = colors[index % colors.length];
      ctx.fill();

      // ラベルを描画
      const labelAngle = currentAngle + sliceAngle / 2;
      const labelX = centerX + Math.cos(labelAngle) * (radius * 0.7);
      const labelY = centerY + Math.sin(labelAngle) * (radius * 0.7);

      ctx.fillStyle = '#ffffff';
      ctx.font = 'bold 14px Arial';
      ctx.textAlign = 'center';
      ctx.fillText(`${time}%`, labelX, labelY);

      currentAngle += sliceAngle;
    });

    // 凡例を表示
    const legendDiv = container.querySelector('#study-time-legend');
    legendDiv.innerHTML = Object.entries(data).map(([subject, time], index) => `
      <div class="legend-item">
        <div class="legend-color" style="background: ${colors[index % colors.length]};"></div>
        <span style="color: var(--text);">${subject}: ${time}%</span>
      </div>
    `).join('');
  }

  // 分野別弱点一覧表示
  function displayWeaknessAnalysis() {
    const tbody = container.querySelector('#weakness-analysis-tbody');
    tbody.innerHTML = currentAnalysisData.weakness.map(item => `
      <tr>
        <td style="color: var(--text); font-weight: bold;">${item.subject}</td>
        <td style="color: var(--text);">${item.field}</td>
        <td style="color: var(--text);">${item.scoreRate}%</td>
        <td>
          <span class="weakness-level-${item.level}">${item.level === 'high' ? '高' : item.level === 'medium' ? '中' : '低'}</span>
        </td>
        <td style="color: var(--text);">${item.suggestion}</td>
        <td style="color: var(--text);">${item.studyTime}分/週</td>
      </tr>
    `).join('');
  }

  // 詳細分析結果を表示
  function showDetailedAnalysis(subject) {
    const detailedDiv = container.querySelector('#detailed-analysis');
    const contentDiv = container.querySelector('#detailed-content');

    // 模擬詳細データを生成
    const detailData = {
      subject: subject,
      currentDeviation: Math.floor(Math.random() * 20) + 50,
      targetDeviation: Math.floor(Math.random() * 10) + 65,
      weakPoints: ['基礎計算', '応用問題', '時間配分'],
      recommendations: [
        '毎日30分の基礎問題演習',
        '週2回の応用問題チャレンジ',
        '模試形式での時間測定練習'
      ]
    };

    contentDiv.innerHTML = `
      <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 20px;">
        <div>
          <h4 style="color: var(--text); margin-bottom: 15px;">${subject} 詳細分析</h4>
          <div style="margin-bottom: 10px;">
            <strong style="color: var(--text);">現在偏差値:</strong> 
            <span style="color: var(--text);">${detailData.currentDeviation}</span>
          </div>
          <div style="margin-bottom: 10px;">
            <strong style="color: var(--text);">目標偏差値:</strong> 
            <span style="color: var(--text);">${detailData.targetDeviation}</span>
          </div>
          <div style="margin-bottom: 10px;">
            <strong style="color: var(--text);">必要上昇値:</strong> 
            <span style="color: ${detailData.targetDeviation - detailData.currentDeviation > 5 ? '#dc3545' : '#28a745'};">
              +${detailData.targetDeviation - detailData.currentDeviation}
            </span>
          </div>
        </div>
        <div>
          <h4 style="color: var(--text); margin-bottom: 15px;">主な弱点分野</h4>
          <ul style="color: var(--text); margin: 0; padding-left: 20px;">
            ${detailData.weakPoints.map(point => `<li>${point}</li>`).join('')}
          </ul>
        </div>
        <div>
          <h4 style="color: var(--text); margin-bottom: 15px;">改善提案</h4>
          <ol style="color: var(--text); margin: 0; padding-left: 20px;">
            ${detailData.recommendations.map(rec => `<li>${rec}</li>`).join('')}
          </ol>
        </div>
      </div>
      <div style="text-align: center; margin-top: 20px;">
        <button id="close-detailed" class="action-btn secondary">詳細を閉じる</button>
      </div>
    `;

    detailedDiv.classList.remove('hidden');

    // 閉じるボタンのイベントリスナー
    container.querySelector('#close-detailed').addEventListener('click', () => {
      detailedDiv.classList.add('hidden');
    });
  }

  // イベントリスナーの設定
  container.querySelector('#analysis-period').addEventListener('change', checkAnalysisReadiness);
  container.querySelector('#target-student').addEventListener('change', checkAnalysisReadiness);
  container.querySelector('#btn-execute-analysis').addEventListener('click', executeAnalysis);

  // イベントデリゲーション
  container.addEventListener('click', (e) => {
    if (e.target.classList.contains('detail-expand-btn')) {
      const subject = e.target.dataset.subject;
      showDetailedAnalysis(subject);
    }
  });

  // 初期データ読み込み
  loadStudents();
  loadSchools();
}

function(container, apiUrl, tables) {
  // 通知履歴テーブルの再描画関数
  function renderNotificationHistory(rows) {
    const tbody = container.querySelector("#notification-history-tbody");
    if (!rows || rows.length === 0) {
      tbody.innerHTML = `
        <tr>
          <td colspan="6" style="text-align: center; padding: 40px; color: var(--text-muted);">
            通知履歴はありません
          </td>
        </tr>
      `;
      return;
    }

    tbody.innerHTML = rows.map(row => `
      <tr data-id="${row.通知履歴ID || row.id || ''}">
        <td>${row.送信日時 || row.通知日時 || ''}</td>
        <td>${row.通知種別 || ''}</td>
        <td>${row.科目 || '全科目'}</td>
        <td>${row.通知内容 || row.変化内容 || ''}</td>
        <td>
          <span style="padding: 4px 8px; border-radius: 4px; font-size: 12px; background: ${row.送信ステータス === '送信完了' ? '#4CAF50' : '#ff9800'}; color: white;">
            ${row.送信ステータス || row.ステータス || '送信完了'}
          </span>
        </td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${row.通知履歴ID || row.id || ''}" style="font-size: 12px; padding: 4px 8px;">
            成績変化詳細
          </button>
        </td>
      </tr>
    `).join("");
  }

  // 初期データの描画
  const notificationHistoryTable = tables.find(t => t.tableName === '通知履歴') || tables[0];
  if (notificationHistoryTable && notificationHistoryTable.records) {
    renderNotificationHistory(notificationHistoryTable.records);
  }

  // エラー・成功メッセージ表示関数
  function showMessage(message, isError = false) {
    const errorEl = container.querySelector("#error-message");
    const successEl = container.querySelector("#success-message");

    errorEl.classList.add("hidden");
    successEl.classList.add("hidden");

    if (isError) {
      errorEl.textContent = message;
      errorEl.classList.remove("hidden");
    } else {
      successEl.textContent = message;
      successEl.classList.remove("hidden");
    }

    setTimeout(() => {
      errorEl.classList.add("hidden");
      successEl.classList.add("hidden");
    }, 5000);
  }

  // バリデーション関数
  function validateForm() {
    const notificationEnabled = container.querySelector("#notification-enabled").checked;

    if (!notificationEnabled) {
      return true; // 通知無効の場合はバリデーションスキップ
    }

    const timing = container.querySelector("#notification-timing").value;
    const subjects = container.querySelectorAll(".subject-checkbox:checked");
    const method = container.querySelector("input[name='notification-method']:checked");
    const deviationThreshold = container.querySelector("#deviation-threshold").value;
    const rankThreshold = container.querySelector("#rank-threshold").value;
    const timeStart = container.querySelector("#time-start").value;
    const timeEnd = container.querySelector("#time-end").value;

    if (!timing) {
      showMessage("通知タイミングを選択してください", true);
      return false;
    }

    if (subjects.length === 0) {
      showMessage("通知対象科目を1つ以上選択してください", true);
      return false;
    }

    if (!method) {
      showMessage("通知方法を選択してください", true);
      return false;
    }

    if (deviationThreshold && (isNaN(deviationThreshold) || deviationThreshold < 0 || deviationThreshold > 100)) {
      showMessage("偏差値閾値は0-100の数値を入力してください", true);
      return false;
    }

    if (rankThreshold && (isNaN(rankThreshold) || rankThreshold < 1)) {
      showMessage("順位閾値は1以上の数値を入力してください", true);
      return false;
    }

    if (timeStart && timeEnd && timeStart >= timeEnd) {
      showMessage("終了時刻は開始時刻より後の時間を設定してください", true);
      return false;
    }

    return true;
  }

  // プレビュー更新関数
  function updatePreview() {
    const preview = container.querySelector("#notification-preview");
    const enabled = container.querySelector("#notification-enabled").checked;
    const timing = container.querySelector("#notification-timing").value;
    const subjects = Array.from(container.querySelectorAll(".subject-checkbox:checked")).map(cb => cb.dataset.subject);
    const method = container.querySelector("input[name='notification-method']:checked");
    const deviationThreshold = container.querySelector("#deviation-threshold").value;
    const rankThreshold = container.querySelector("#rank-threshold").value;

    if (!enabled) {
      preview.innerHTML = `
        <div style="display: flex; align-items: center; gap: 10px; margin-bottom: 10px;">
          <div style="width: 8px; height: 8px; background: #9e9e9e; border-radius: 50%;"></div>
          <strong style="color: var(--text);">通知設定: 無効</strong>
        </div>
        <p style="color: var(--text-muted); margin: 0;">成績変化通知は無効に設定されています。</p>
      `;
      return;
    }

    const timingText = {
      immediate: "即座",
      daily: "1日後",
      weekly: "1週間後",
      monthly: "1ヶ月後"
    }[timing] || "未設定";

    const methodText = method ? {
      app: "アプリ内通知",
      email: "メール",
      sms: "SMS",
      push: "プッシュ通知"
    }[method.value] : "未設定";

    preview.innerHTML = `
      <div style="display: flex; align-items: center; gap: 10px; margin-bottom: 10px;">
        <div style="width: 8px; height: 8px; background: #4CAF50; border-radius: 50%;"></div>
        <strong style="color: var(--text);">成績変化通知プレビュー</strong>
      </div>
      <p style="color: var(--text); margin: 0; line-height: 1.5;">
        【${subjects.length > 0 ? subjects.join('、') : '未選択'}】の成績に変化がありました。<br>
        ${deviationThreshold ? `偏差値が${deviationThreshold}ポイント` : ''}${deviationThreshold && rankThreshold ? '、' : ''}${rankThreshold ? `順位が${rankThreshold}位` : ''}変動しています。<br>
        通知方法: ${methodText} | タイミング: ${timingText}
      </p>
    `;
  }

  // 全科目選択の制御
  const subjectAll = container.querySelector("#subject-all");
  const subjectCheckboxes = container.querySelectorAll(".subject-checkbox");

  subjectAll.addEventListener("change", function() {
    subjectCheckboxes.forEach(cb => {
      cb.checked = this.checked;
    });
    updatePreview();
  });

  subjectCheckboxes.forEach(cb => {
    cb.addEventListener("change", function() {
      const allChecked = Array.from(subjectCheckboxes).every(checkbox => checkbox.checked);
      const noneChecked = Array.from(subjectCheckboxes).every(checkbox => !checkbox.checked);

      if (allChecked) {
        subjectAll.checked = true;
        subjectAll.indeterminate = false;
      } else if (noneChecked) {
        subjectAll.checked = false;
        subjectAll.indeterminate = false;
      } else {
        subjectAll.checked = false;
        subjectAll.indeterminate = true;
      }
      updatePreview();
    });
  });

  // フォーム変更時のプレビュー更新
  container.addEventListener("change", updatePreview);
  container.addEventListener("input", updatePreview);

  // 設定保存ボタン
  container.querySelector("#btn-save").addEventListener("click", async function() {
    if (!validateForm()) {
      return;
    }

    try {
      const formData = {
        通知有効フラグ: container.querySelector("#notification-enabled").checked,
        通知タイミング: container.querySelector("#notification-timing").value,
        通知方法: container.querySelector("input[name='notification-method']:checked")?.value || '',
        偏差値変動閾値: parseInt(container.querySelector("#deviation-threshold").value) || null,
        順位変動閾値: parseInt(container.querySelector("#rank-threshold").value) || null,
        対象科目: Array.from(container.querySelectorAll(".subject-checkbox:checked")).map(cb => cb.dataset.subject).join(','),
        通知開始時刻: container.querySelector("#time-start").value,
        通知終了時刻: container.querySelector("#time-end").value,
        緊急通知設定: container.querySelector("#emergency-notification").checked,
        受験生ID: "sample-student-id",
        保護者ID: "sample-parent-id",
        通知種別コード: "grade_change",
        通知種別名: "成績変化通知",
        作成日時: new Date().toISOString(),
        更新日時: new Date().toISOString(),
        作成者ID: "sample-user-id",
        更新者ID: "sample-user-id"
      };

      const saved = await window.aivicApi.save(0, formData);
      if (saved) {
        showMessage("通知設定が正常に保存されました");
        updatePreview();
      } else {
        showMessage("設定の保存に失敗しました。ネットワーク接続を確認してください。", true);
      }
    } catch (error) {
      showMessage("設定の保存中にエラーが発生しました", true);
    }
  });

  // テスト通知送信ボタン
  container.querySelector("#btn-test-notification").addEventListener("click", async function() {
    const method = container.querySelector("input[name='notification-method']:checked");
    if (!method) {
      showMessage("通知方法を選択してからテスト通知を送信してください", true);
      return;
    }

    try {
      const testData = {
        通知種別: "テスト通知",
        通知タイトル: "成績変化通知テスト",
        通知内容: "これはテスト通知です。成績変化通知が正常に動作しています。",
        通知方法: method.value,
        送信日時: new Date().toISOString(),
        送信ステータス: "送信完了",
        受験生ID: "sample-student-id",
        保護者ID: "sample-parent-id",
        優先度: "中",
        作成日時: new Date().toISOString(),
        更新日時: new Date().toISOString()
      };

      const saved = await window.aivicApi.save(1, testData);
      if (saved) {
        showMessage("テスト通知を送信しました");
        // 通知履歴を再読み込み
        const rows = await window.aivicApi.list(1);
        if (rows) {
          renderNotificationHistory(rows);
        }
      } else {
        showMessage("テスト通知の送信に失敗しました", true);
      }
    } catch (error) {
      showMessage("テスト通知送信中にエラーが発生しました", true);
    }
  });

  // 通知履歴の詳細ボタンクリック
  container.addEventListener("click", function(e) {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      window.showScreen("scr-1778233732425");
    }
  });

  // 初期プレビュー表示
  updatePreview();

  // 初期データ読み込み
  window.aivicApi.list(0).then(rows => {
    if (rows && rows.length > 0) {
      const latestSetting = rows[rows.length - 1];
      // 設定値を復元
      if (latestSetting.通知有効フラグ !== undefined) {
        container.querySelector("#notification-enabled").checked = latestSetting.通知有効フラグ;
      }
      if (latestSetting.通知タイミング) {
        container.querySelector("#notification-timing").value = latestSetting.通知タイミング;
      }
      if (latestSetting.通知方法) {
        const methodRadio = container.querySelector(`input[name='notification-method'][value='${latestSetting.通知方法}']`);
        if (methodRadio) methodRadio.checked = true;
      }
      if (latestSetting.偏差値変動閾値) {
        container.querySelector("#deviation-threshold").value = latestSetting.偏差値変動閾値;
      }
      if (latestSetting.順位変動閾値) {
        container.querySelector("#rank-threshold").value = latestSetting.順位変動閾値;
      }
      if (latestSetting.対象科目) {
        const subjects = latestSetting.対象科目.split(',');
        subjects.forEach(subject => {
          const checkbox = container.querySelector(`.subject-checkbox[data-subject='${subject}']`);
          if (checkbox) checkbox.checked = true;
        });
      }
      if (latestSetting.通知開始時刻) {
        container.querySelector("#time-start").value = latestSetting.通知開始時刻;
      }
      if (latestSetting.通知終了時刻) {
        container.querySelector("#time-end").value = latestSetting.通知終了時刻;
      }
      if (latestSetting.緊急通知設定 !== undefined) {
        container.querySelector("#emergency-notification").checked = latestSetting.緊急通知設定;
      }
      updatePreview();
    }
  });

  // 通知履歴データ読み込み
  window.aivicApi.list(1).then(rows => {
    if (rows) {
      renderNotificationHistory(rows);
    }
  });
}

function(container, apiUrl, tables) {
  // URLパラメータから受験生IDと模試IDを取得
  const urlParams = new URLSearchParams(window.location.search);
  const studentId = urlParams.get('studentId') || 'default-student-id';
  const examId = urlParams.get('examId') || 'default-exam-id';

  // エラー表示関数
  function showError(message) {
    container.innerHTML = `<div class="error-message">${message}</div>`;
  }

  // ローディング表示関数
  function showLoading() {
    container.querySelector('.content-grid').innerHTML = '<div class="loading">データを読み込み中...</div>';
  }

  // 科目別成績テーブルの再描画
  function renderSubjectScores(scores) {
    const tbody = container.querySelector('#subject-scores-tbody');
    if (!scores || scores.length === 0) {
      tbody.innerHTML = '<tr><td colspan="7" class="muted">科目別成績データがありません</td></tr>';
      return;
    }

    tbody.innerHTML = scores.map(score => {
      const isWeak = score.偏差値 && score.偏差値 < 50;
      const prevChange = score.前回比較 || 0;
      const changeClass = prevChange > 0 ? 'positive' : prevChange < 0 ? 'negative' : 'neutral';
      const changeText = prevChange > 0 ? `+${prevChange}` : prevChange < 0 ? `${prevChange}` : '±0';

      return `
        <tr ${isWeak ? 'class="highlight"' : ''} data-id="${score.成績ID}">
          <td><strong>${score.科目名 || '-'}</strong></td>
          <td>${score.得点 || 0}</td>
          <td>${score.満点 || 100}</td>
          <td>${score.偏差値 || '-'}</td>
          <td>${score.順位 || '-'}</td>
          <td>${score.平均点 || '-'}</td>
          <td><span class="change-indicator ${changeClass}">${changeText}</span></td>
        </tr>
      `;
    }).join('');
  }

  // 科目別偏差値グラフの描画
  function drawSubjectDeviationChart(scores) {
    const canvas = container.querySelector('#subject-deviation-chart');
    const ctx = canvas.getContext('2d');

    if (!scores || scores.length === 0) {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '14px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('グラフデータがありません', canvas.width / 2, canvas.height / 2);
      return;
    }

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;
    const barWidth = chartWidth / scores.length;

    // Y軸（偏差値0-100）
    ctx.strokeStyle = '#e2e8f0';
    ctx.lineWidth = 1;
    for (let i = 0; i <= 10; i++) {
      const y = padding + (chartHeight * i / 10);
      ctx.beginPath();
      ctx.moveTo(padding, y);
      ctx.lineTo(padding + chartWidth, y);
      ctx.stroke();

      ctx.fillStyle = '#64748b';
      ctx.font = '12px sans-serif';
      ctx.textAlign = 'right';
      ctx.fillText((100 - i * 10).toString(), padding - 10, y + 4);
    }

    // 棒グラフ描画
    scores.forEach((score, index) => {
      const deviation = score.偏差値 || 0;
      const barHeight = (deviation / 100) * chartHeight;
      const x = padding + index * barWidth + barWidth * 0.1;
      const y = padding + chartHeight - barHeight;
      const width = barWidth * 0.8;

      // 棒の色（偏差値50未満は赤系、50以上は青系）
      ctx.fillStyle = deviation < 50 ? '#ef4444' : '#3b82f6';
      ctx.fillRect(x, y, width, barHeight);

      // 科目名
      ctx.fillStyle = '#1e293b';
      ctx.font = '11px sans-serif';
      ctx.textAlign = 'center';
      ctx.save();
      ctx.translate(x + width / 2, padding + chartHeight + 15);
      ctx.rotate(-Math.PI / 4);
      ctx.fillText(score.科目名 || '', 0, 0);
      ctx.restore();

      // 偏差値表示
      ctx.fillStyle = '#1e293b';
      ctx.font = '10px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(deviation.toString(), x + width / 2, y - 5);
    });
  }

  // 偏差値推移チャートの描画
  function drawDeviationTrendChart(historyData) {
    const canvas = container.querySelector('#deviation-trend-chart');
    const ctx = canvas.getContext('2d');

    if (!historyData || historyData.length === 0) {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '14px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('推移データがありません', canvas.width / 2, canvas.height / 2);
      return;
    }

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const padding = 60;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;

    // グリッド線
    ctx.strokeStyle = '#e2e8f0';
    ctx.lineWidth = 1;
    for (let i = 0; i <= 10; i++) {
      const y = padding + (chartHeight * i / 10);
      ctx.beginPath();
      ctx.moveTo(padding, y);
      ctx.lineTo(padding + chartWidth, y);
      ctx.stroke();

      ctx.fillStyle = '#64748b';
      ctx.font = '12px sans-serif';
      ctx.textAlign = 'right';
      ctx.fillText((100 - i * 10).toString(), padding - 10, y + 4);
    }

    // 折れ線グラフ
    if (historyData.length > 1) {
      ctx.strokeStyle = '#3b82f6';
      ctx.lineWidth = 2;
      ctx.beginPath();

      historyData.forEach((data, index) => {
        const x = padding + (index / (historyData.length - 1)) * chartWidth;
        const y = padding + chartHeight - ((data.偏差値 || 0) / 100) * chartHeight;

        if (index === 0) {
          ctx.moveTo(x, y);
        } else {
          ctx.lineTo(x, y);
        }
      });

      ctx.stroke();

      // データポイント
      historyData.forEach((data, index) => {
        const x = padding + (index / (historyData.length - 1)) * chartWidth;
        const y = padding + chartHeight - ((data.偏差値 || 0) / 100) * chartHeight;

        ctx.fillStyle = '#3b82f6';
        ctx.beginPath();
        ctx.arc(x, y, 4, 0, 2 * Math.PI);
        ctx.fill();

        // 日付ラベル
        ctx.fillStyle = '#64748b';
        ctx.font = '10px sans-serif';
        ctx.textAlign = 'center';
        const date = new Date(data.測定日);
        const dateStr = `${date.getMonth() + 1}/${date.getDate()}`;
        ctx.fillText(dateStr, x, padding + chartHeight + 20);
      });
    }
  }

  // 弱点科目の表示
  function renderWeakSubjects(scores) {
    const weakSubjectsContainer = container.querySelector('#weak-subjects');
    const weakSubjects = scores.filter(score => score.偏差値 && score.偏差値 < 50);

    if (weakSubjects.length === 0) {
      weakSubjectsContainer.innerHTML = '<div class="weak-subject-item"><span class="subject-name">弱点なし</span><span class="weakness-detail">すべての科目で平均以上の成績です</span></div>';
      return;
    }

    weakSubjectsContainer.innerHTML = weakSubjects.map(subject => `
      <div class="weak-subject-item highlight">
        <span class="subject-name">${subject.科目名}</span>
        <span class="weakness-detail">偏差値 ${subject.偏差値} (平均-${50 - subject.偏差値})</span>
      </div>
    `).join('');
  }

  // 志望校合格可能性の表示
  function renderAdmissionPossibility(possibilityData) {
    const container_elem = container.querySelector('#admission-possibility');
    if (!possibilityData || possibilityData.length === 0) {
      container_elem.innerHTML = '<div class="possibility-item"><span class="school-name">志望校未登録</span><span class="possibility-rate">-</span><span class="judgment-rank">-</span></div>';
      return;
    }

    container_elem.innerHTML = possibilityData.map(data => `
      <div class="possibility-item">
        <span class="school-name">${data.学校名 || '志望校'}</span>
        <span class="possibility-rate">${data.合格可能性パーセント || 0}%</span>
        <span class="judgment-rank">${data.合格可能性判定 || '-'}</span>
      </div>
    `).join('');
  }

  // 前回比較の表示
  function renderPreviousComparison(currentData, previousData) {
    const prevTotalDeviation = container.querySelector('#prev-total-deviation');
    const prevTotalScore = container.querySelector('#prev-total-score');
    const deviationChange = container.querySelector('#deviation-change');
    const scoreChange = container.querySelector('#score-change');

    if (!previousData) {
      prevTotalDeviation.textContent = '前回データなし';
      prevTotalScore.textContent = '前回データなし';
      deviationChange.textContent = '-';
      scoreChange.textContent = '-';
      deviationChange.className = 'change-indicator neutral';
      scoreChange.className = 'change-indicator neutral';
      return;
    }

    const currentDeviation = currentData.総合偏差値 || 0;
    const previousDeviation = previousData.総合偏差値 || 0;
    const currentScore = currentData.総合得点 || 0;
    const previousScore = previousData.総合得点 || 0;

    const deviationDiff = currentDeviation - previousDeviation;
    const scoreDiff = currentScore - previousScore;

    prevTotalDeviation.textContent = previousDeviation.toString();
    prevTotalScore.textContent = previousScore.toString();

    deviationChange.textContent = deviationDiff > 0 ? `+${deviationDiff}` : deviationDiff < 0 ? `${deviationDiff}` : '±0';
    scoreChange.textContent = scoreDiff > 0 ? `+${scoreDiff}` : scoreDiff < 0 ? `${scoreDiff}` : '±0';

    deviationChange.className = `change-indicator ${deviationDiff > 0 ? 'positive' : deviationDiff < 0 ? 'negative' : 'neutral'}`;
    scoreChange.className = `change-indicator ${scoreDiff > 0 ? 'positive' : scoreDiff < 0 ? 'negative' : 'neutral'}`;
  }

  // メインデータ読み込み
  async function loadScoreDetail() {
    try {
      showLoading();

      // 各テーブルからデータを取得
      const [examResults, subjectScores, deviationHistory, admissionResults, analysisResults] = await Promise.all([
        window.aivicApi.list(2), // 模試結果データ
        window.aivicApi.list(3), // 科目別成績データ
        window.aivicApi.list(4), // 偏差値履歴データ
        window.aivicApi.list(7), // 合格可能性算出結果
        window.aivicApi.list(9)  // 科目別分析結果
      ]);

      if (!examResults) {
        showError('データの取得に失敗しました。ネットワーク接続を確認してください。');
        return;
      }

      // 対象の模試結果を取得
      const targetExam = examResults.find(exam => exam.受験生ID === studentId && exam.模試結果ID === examId);
      if (!targetExam) {
        showError('指定された模試結果が見つかりません。');
        return;
      }

      // 基本情報の表示
      container.querySelector('#student-name').textContent = `受験生ID: ${studentId}`;
      container.querySelector('#exam-info').textContent = `${targetExam.模試名} (${new Date(targetExam.受験日).toLocaleDateString()})`;
      container.querySelector('#total-deviation').textContent = targetExam.総合偏差値 || '-';
      container.querySelector('#total-score').textContent = `${targetExam.総合得点 || 0}点`;
      container.querySelector('#national-rank').textContent = targetExam.全国順位 ? `${targetExam.全国順位}位/${targetExam.全国受験者数}人中` : '-';
      container.querySelector('#school-rank').textContent = targetExam.都道府県順位 ? `${targetExam.都道府県順位}位/${targetExam.都道府県受験者数}人中` : '-';

      // 科目別成績の表示
      const relatedSubjectScores = subjectScores ? subjectScores.filter(score => score.受験生ID === studentId && score.模試ID === examId) : [];
      renderSubjectScores(relatedSubjectScores);
      renderWeakSubjects(relatedSubjectScores);

      // グラフの描画
      drawSubjectDeviationChart(relatedSubjectScores);

      const studentDeviationHistory = deviationHistory ? deviationHistory.filter(history => history.受験生ID === studentId).sort((a, b) => new Date(a.測定日) - new Date(b.測定日)) : [];
      drawDeviationTrendChart(studentDeviationHistory);

      // 合格可能性の表示
      const studentAdmissionResults = admissionResults ? admissionResults.filter(result => result.受験生ID === studentId) : [];
      renderAdmissionPossibility(studentAdmissionResults);

      // 前回比較の表示
      const previousExam = examResults.filter(exam => exam.受験生ID === studentId && exam.模試結果ID !== examId).sort((a, b) => new Date(b.受験日) - new Date(a.受験日))[0];
      renderPreviousComparison(targetExam, previousExam);

      // 成績分析コメントの表示
      const studentAnalysis = analysisResults ? analysisResults.find(analysis => analysis.受験生ID === studentId) : null;
      const commentArea = container.querySelector('#analysis-comment');
      if (studentAnalysis && studentAnalysis.保護者向けコメント) {
        commentArea.textContent = studentAnalysis.保護者向けコメント;
      } else {
        commentArea.textContent = '成績分析コメントはありません。';
      }

    } catch (error) {
      console.error('データ読み込みエラー:', error);
      showError('データの読み込み中にエラーが発生しました。');
    }
  }

  // 初期化
  loadScoreDetail();
}

function(container, apiUrl, tables) {
  // テーブルインデックス
  const SCRAPING_SETTINGS_TABLE = 0; // Webスクレイピング設定マスタ
  const SITE_INFO_TABLE = 1; // 予備校サイト情報マスタ
  const DATA_LOG_TABLE = 2; // データ取得ログ
  const ERROR_LOG_TABLE = 3; // エラーログ

  let allServices = [];
  let allLogs = [];
  let currentFilters = {};

  // ステータスバッジを生成
  function createStatusBadge(status) {
    let className = 'status-inactive';
    if (status === '正常' || status === '連携中') className = 'status-normal';
    else if (status === 'エラー' || status === '接続失敗') className = 'status-error';
    else if (status === '警告') className = 'status-warning';

    return `<span class="status-badge ${className}">${status}</span>`;
  }

  // 日時フォーマット
  function formatDateTime(dateStr) {
    if (!dateStr) return '-';
    try {
      const date = new Date(dateStr);
      return date.toLocaleString('ja-JP', {
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit'
      });
    } catch (e) {
      return dateStr;
    }
  }

  // 処理時間フォーマット
  function formatDuration(seconds) {
    if (!seconds) return '-';
    if (seconds < 60) return `${seconds}秒`;
    const minutes = Math.floor(seconds / 60);
    const remainingSeconds = seconds % 60;
    return `${minutes}分${remainingSeconds}秒`;
  }

  // サービス一覧を描画
  function renderServices(services) {
    const tbody = container.querySelector('#services-tbody');

    if (!services || services.length === 0) {
      tbody.innerHTML = `
        <tr>
          <td colspan="7" style="text-align: center; padding: 40px; color: var(--text-muted);">
            連携中のサービスはありません
          </td>
        </tr>
      `;
      return;
    }

    tbody.innerHTML = services.map(service => `
      <tr data-id="${service.id}">
        <td>
          <div style="font-weight: bold; color: var(--text);">${service.設定名 || service.対象サイト名 || '-'}</div>
          <div class="muted" style="font-size: 12px;">${service.対象サイト名 || ''}</div>
        </td>
        <td>${createStatusBadge(service.有効フラグ ? '正常' : '未連携')}</td>
        <td>${formatDateTime(service.最終実行日時)}</td>
        <td style="text-align: right;">${service.取得件数 || 0}件</td>
        <td>${service.実行頻度 || '-'}</td>
        <td>
          ${service.エラー通知フラグ ? '<span style="color: #dc3545;">エラーあり</span>' : '<span style="color: #28a745;">正常</span>'}
        </td>
        <td>
          <button class="action-btn secondary view-detail-btn" data-id="${service.id}">詳細</button>
          <button class="action-btn secondary sync-btn" data-id="${service.id}">同期</button>
        </td>
      </tr>
    `).join('');

    // サマリー更新
    updateSummary(services);
  }

  // ログ一覧を描画
  function renderLogs(logs) {
    const tbody = container.querySelector('#logs-tbody');

    if (!logs || logs.length === 0) {
      tbody.innerHTML = `
        <tr>
          <td colspan="7" style="text-align: center; padding: 40px; color: var(--text-muted);">
            データ取得ログはありません
          </td>
        </tr>
      `;
      return;
    }

    tbody.innerHTML = logs.map(log => `
      <tr data-id="${log.id}">
        <td>${formatDateTime(log.実行開始日時)}</td>
        <td>${log.データソース名 || '-'}</td>
        <td>${createStatusBadge(log.処理ステータス || '不明')}</td>
        <td style="text-align: right;">${log.取得件数 || 0}件</td>
        <td style="text-align: right; color: ${(log.エラー件数 || 0) > 0 ? '#dc3545' : 'var(--text)'};">
          ${log.エラー件数 || 0}件
        </td>
        <td>${formatDuration(log.レスポンス時間 ? Math.floor(log.レスポンス時間 / 1000) : null)}</td>
        <td>
          <button class="action-btn secondary view-log-btn" data-id="${log.id}">詳細</button>
        </td>
      </tr>
    `).join('');
  }

  // サマリー情報を更新
  function updateSummary(services) {
    const totalServices = services.length;
    const totalRecords = services.reduce((sum, s) => sum + (s.取得件数 || 0), 0);

    // 最新の実行日時を取得
    const lastSyncTimes = services
      .map(s => s.最終実行日時)
      .filter(t => t)
      .sort((a, b) => new Date(b) - new Date(a));

    const lastSyncTime = lastSyncTimes.length > 0 ? formatDateTime(lastSyncTimes[0]) : '-';

    // 次回実行予定時刻を取得
    const nextSyncTimes = services
      .map(s => s.次回実行予定日時)
      .filter(t => t)
      .sort((a, b) => new Date(a) - new Date(b));

    const nextSyncTime = nextSyncTimes.length > 0 ? formatDateTime(nextSyncTimes[0]) : '-';

    container.querySelector('#total-services').textContent = totalServices;
    container.querySelector('#total-records').textContent = totalRecords;
    container.querySelector('#last-sync-time').textContent = lastSyncTime;
    container.querySelector('#next-sync-time').textContent = nextSyncTime;
  }

  // フィルター適用
  function applyFilters() {
    const statusFilter = container.querySelector('#filter-status').value;
    const sourceFilter = container.querySelector('#filter-source').value.toLowerCase();
    const dateFromFilter = container.querySelector('#filter-date-from').value;
    const dateToFilter = container.querySelector('#filter-date-to').value;

    let filteredServices = allServices;

    // ステータスフィルター
    if (statusFilter) {
      filteredServices = filteredServices.filter(service => {
        const status = service.有効フラグ ? '正常' : '未連携';
        return status === statusFilter;
      });
    }

    // データソースフィルター
    if (sourceFilter) {
      filteredServices = filteredServices.filter(service => {
        const searchText = `${service.設定名 || ''} ${service.対象サイト名 || ''}`.toLowerCase();
        return searchText.includes(sourceFilter);
      });
    }

    // 日付フィルター
    if (dateFromFilter || dateToFilter) {
      filteredServices = filteredServices.filter(service => {
        if (!service.最終実行日時) return false;
        const serviceDate = new Date(service.最終実行日時).toISOString().split('T')[0];

        if (dateFromFilter && serviceDate < dateFromFilter) return false;
        if (dateToFilter && serviceDate > dateToFilter) return false;

        return true;
      });
    }

    renderServices(filteredServices);
  }

  // エラー詳細を表示
  function showErrorDetails(logId) {
    const log = allLogs.find(l => l.id === logId);
    if (!log) return;

    container.querySelector('#error-datetime').textContent = formatDateTime(log.実行開始日時);
    container.querySelector('#error-code').textContent = log.エラーコード || 'N/A';
    container.querySelector('#error-message').textContent = log.エラーメッセージ || 'エラーメッセージがありません';

    // 対処方法を生成
    let solution = '以下をお試しください:\n';
    if (log.エラーコード === 'NETWORK_ERROR') {
      solution += '• ネットワーク接続を確認してください\n• しばらく時間をおいて再度お試しください';
    } else if (log.エラーコード === 'AUTH_ERROR') {
      solution += '• 認証情報を確認してください\n• 連携設定を見直してください';
    } else if (log.エラーコード === 'TIMEOUT') {
      solution += '• サーバーの応答が遅い可能性があります\n• 時間をおいて再度お試しください';
    } else {
      solution += '• 手動でデータ取得を再実行してください\n• 問題が続く場合はサポートにお問い合わせください';
    }

    container.querySelector('#error-solution').textContent = solution;
    container.querySelector('#error-modal').classList.remove('hidden');
  }

  // 手動データ取得を実行
  async function executeManualSync() {
    if (!confirm('手動でデータ取得を実行しますか？\n処理には時間がかかる場合があります。')) {
      return;
    }

    container.querySelector('#loading-modal').classList.remove('hidden');

    try {
      // 模擬的な処理時間
      await new Promise(resolve => setTimeout(resolve, 2000));

      // 成功メッセージ
      alert('データ取得が完了しました。');

      // データを再読み込み
      await loadData();
    } catch (error) {
      alert('データ取得中にエラーが発生しました: ' + error.message);
    } finally {
      container.querySelector('#loading-modal').classList.remove('hidden');
    }
  }

  // データを読み込み
  async function loadData() {
    try {
      // スクレイピング設定とサイト情報を連携サービスとして表示
      const scrapingSettings = await window.aivicApi.list(SCRAPING_SETTINGS_TABLE) || [];
      const siteInfo = await window.aivicApi.list(SITE_INFO_TABLE) || [];
      const dataLogs = await window.aivicApi.list(DATA_LOG_TABLE) || [];

      // サービス情報を統合
      allServices = [
        ...scrapingSettings.map(s => ({
          ...s,
          type: 'scraping',
          取得件数: Math.floor(Math.random() * 100) + 1 // 模擬データ
        })),
        ...siteInfo.map(s => ({
          ...s,
          type: 'site',
          設定名: s.予備校名,
          対象サイト名: s.予備校名,
          有効フラグ: s.利用可能状態,
          取得件数: Math.floor(Math.random() * 50) + 1 // 模擬データ
        }))
      ];

      allLogs = dataLogs;

      renderServices(allServices);
      renderLogs(allLogs);
    } catch (error) {
      console.error('データ読み込みエラー:', error);
      renderServices([]);
      renderLogs([]);
    }
  }

  // 初期データ読み込み
  loadData();

  // イベントリスナー設定
  container.querySelector('#btn-filter').addEventListener('click', applyFilters);

  container.querySelector('#btn-clear-filter').addEventListener('click', () => {
    container.querySelector('#filter-status').value = '';
    container.querySelector('#filter-source').value = '';
    container.querySelector('#filter-date-from').value = '';
    container.querySelector('#filter-date-to').value = '';
    renderServices(allServices);
  });

  container.querySelector('#btn-manual-sync').addEventListener('click', executeManualSync);

  container.querySelector('#btn-settings').addEventListener('click', () => {
    window.showScreen('scr-1778233647948'); // データ統合管理画面
  });

  container.querySelector('#btn-close-modal').addEventListener('click', () => {
    container.querySelector('#error-modal').classList.add('hidden');
  });

  // イベントデリゲーション
  container.addEventListener('click', async (e) => {
    const viewDetailBtn = e.target.closest('.view-detail-btn');
    const syncBtn = e.target.closest('.sync-btn');
    const viewLogBtn = e.target.closest('.view-log-btn');

    if (viewDetailBtn) {
      const serviceId = viewDetailBtn.dataset.id;
      // 詳細画面への遷移（実装に応じて調整）
      alert('サービス詳細画面は今後実装予定です');
    }

    if (syncBtn) {
      const serviceId = syncBtn.dataset.id;
      if (confirm('このサービスのデータを手動取得しますか？')) {
        try {
          container.querySelector('#loading-modal').classList.remove('hidden');
          await new Promise(resolve => setTimeout(resolve, 1500));
          alert('データ取得が完了しました');
          await loadData();
        } catch (error) {
          alert('データ取得に失敗しました: ' + error.message);
        } finally {
          container.querySelector('#loading-modal').classList.add('hidden');
        }
      }
    }

    if (viewLogBtn) {
      const logId = viewLogBtn.dataset.id;
      showErrorDetails(logId);
    }
  });

  // モーダル外クリックで閉じる
  container.querySelector('#error-modal').addEventListener('click', (e) => {
    if (e.target.id === 'error-modal') {
      container.querySelector('#error-modal').classList.add('hidden');
    }
  });

  container.querySelector('#loading-modal').addEventListener('click', (e) => {
    if (e.target.id === 'loading-modal') {
      // 処理中は閉じない
    }
  });
}
